"""Audit categorized workspace documentation."""

from __future__ import annotations

import argparse
import fnmatch
import json
from pathlib import Path
from typing import Any


JsonMap = dict[str, Any]


def audit_docs(repo_root: Path, registry_path: Path | None = None) -> JsonMap:
    """Return a deterministic docs registry audit report."""

    repo_root = repo_root.resolve()
    registry_path = registry_path or repo_root / "_docs" / "registry.json"
    registry = _read_json(registry_path)
    docs_root = repo_root / registry.get("docs_root", "_docs")
    allowed_root_files = set(registry.get("allowed_root_files", []))
    categories = registry.get("categories", [])
    required_documents = registry.get("required_documents", [])
    language_pair_exceptions = set(registry.get("language_pair_policy", {}).get("exceptions", []))

    gaps: list[str] = []
    warnings: list[str] = []
    category_reports: list[JsonMap] = []

    if not docs_root.exists():
        gaps.append(f"Docs root does not exist: {docs_root}")
        return _report(repo_root, registry_path, category_reports, gaps, warnings)

    markdown_files = sorted(path for path in docs_root.rglob("*.md") if path.is_file())
    markdown_rel = {path.relative_to(repo_root).as_posix() for path in markdown_files}
    category_paths = {category["id"]: repo_root / category["path"] for category in categories}

    for required in required_documents:
        if not (repo_root / required).exists():
            gaps.append(f"Required document is missing: {required}")

    for path in markdown_files:
        rel_to_docs = path.relative_to(docs_root)
        if len(rel_to_docs.parts) == 1 and path.name not in allowed_root_files:
            gaps.append(f"Markdown file is not allowed at _docs root: {path.relative_to(repo_root).as_posix()}")

    for category in categories:
        category_id = category["id"]
        category_path = category_paths[category_id]
        include_patterns = category.get("include_patterns", [])
        required_index_files = category.get("required_index_files", [])
        category_docs: list[str] = []

        if not category_path.exists() or not category_path.is_dir():
            gaps.append(f"Docs category folder is missing: {category.get('path')}")
            continue

        for index_file in required_index_files:
            if not (category_path / index_file).exists():
                gaps.append(f"Docs category {category_id} is missing index file: {index_file}")

        for path in sorted(category_path.rglob("*.md")):
            rel = path.relative_to(repo_root).as_posix()
            name = path.name
            if name in required_index_files:
                continue
            category_docs.append(rel)
            if not _matches_any(name, include_patterns):
                gaps.append(
                    f"Document {rel} does not match include_patterns for category {category_id}: {include_patterns}"
                )

        category_reports.append(
            {
                "id": category_id,
                "path": category.get("path"),
                "documents_count": len(category_docs),
                "required_index_files": required_index_files,
            }
        )

    for path in markdown_files:
        rel = path.relative_to(repo_root).as_posix()
        if _is_allowed_root_markdown(path, docs_root, allowed_root_files):
            continue
        containing_categories = [
            category_id
            for category_id, category_path in category_paths.items()
            if _is_relative_to(path, category_path)
        ]
        if not containing_categories:
            gaps.append(f"Document is not inside a registered docs category: {rel}")
        elif len(containing_categories) > 1:
            gaps.append(f"Document is inside multiple docs categories: {rel}")

    for rel in sorted(markdown_rel):
        if rel in language_pair_exceptions:
            continue
        counterpart = _language_counterpart(rel)
        if counterpart and counterpart not in markdown_rel and counterpart not in language_pair_exceptions:
            gaps.append(f"Language companion is missing for {rel}: expected {counterpart}")

    if not categories:
        gaps.append("Docs registry has no categories.")
    if not required_documents:
        warnings.append("Docs registry has no required_documents; future sessions may miss durable docs.")

    return _report(repo_root, registry_path, category_reports, gaps, warnings)


def main() -> int:
    parser = argparse.ArgumentParser(description="Audit categorized _docs structure.")
    parser.add_argument("--repo-root", default=".", help="Repository root. Defaults to current directory.")
    parser.add_argument("--registry", default="", help="Optional docs registry JSON path.")
    parser.add_argument("--check", action="store_true", help="Exit with code 1 when gaps are found.")
    args = parser.parse_args()

    repo_root = Path(args.repo_root)
    registry = Path(args.registry) if args.registry else None
    report = audit_docs(repo_root, registry)
    print(json.dumps(report, ensure_ascii=False, indent=2))
    return 1 if args.check and report["requires_rework"] else 0


def _report(
    repo_root: Path,
    registry_path: Path,
    category_reports: list[JsonMap],
    gaps: list[str],
    warnings: list[str],
) -> JsonMap:
    return {
        "status": "docs_rework_required" if gaps else "docs_ready",
        "requires_rework": bool(gaps),
        "repo_root": str(repo_root),
        "registry_path": str(registry_path),
        "checks": {
            "categories_count": len(category_reports),
            "documents_count": sum(report["documents_count"] for report in category_reports),
            "gaps_count": len(gaps),
            "warnings_count": len(warnings),
        },
        "categories": category_reports,
        "gaps": gaps,
        "warnings": warnings,
        "follow_up_actions": [f"Resolve docs gap: {gap}" for gap in gaps],
    }


def _matches_any(name: str, patterns: list[str]) -> bool:
    return any(fnmatch.fnmatch(name, pattern) for pattern in patterns)


def _is_allowed_root_markdown(path: Path, docs_root: Path, allowed_root_files: set[str]) -> bool:
    rel_to_docs = path.relative_to(docs_root)
    return len(rel_to_docs.parts) == 1 and path.name in allowed_root_files


def _is_relative_to(path: Path, other: Path) -> bool:
    try:
        path.relative_to(other)
        return True
    except ValueError:
        return False


def _language_counterpart(path: str) -> str:
    if path.endswith(".ko.md"):
        return f"{path[:-6]}.en.md"
    if path.endswith(".en.md"):
        return f"{path[:-6]}.ko.md"
    return ""


def _read_json(path: Path) -> JsonMap:
    return json.loads(path.read_text(encoding="utf-8"))


if __name__ == "__main__":
    raise SystemExit(main())

"""Audit repository naming conventions against the workspace naming policy."""

from __future__ import annotations

import argparse
import json
import re
from pathlib import Path
from typing import Any


JsonMap = dict[str, Any]

KEBAB_RE = re.compile(r"^[a-z0-9]+(-[a-z0-9]+)*$")
UNDERSCORE_KEBAB_RE = re.compile(r"^_[a-z0-9]+(-[a-z0-9]+)*$")
DOT_KEBAB_RE = re.compile(r"^\.[a-z0-9]+(-[a-z0-9]+)*$")
SNAKE_RE = re.compile(r"^[a-z][a-z0-9_]*$")
DATE_SLUG_RE = re.compile(r"^\d{4}-\d{2}-\d{2}-[a-z0-9]+(-[a-z0-9]+)*$")
DOC_NAME_RE = re.compile(r"^[a-z0-9]+(-[a-z0-9]+)*(\.(ko|en))?\.md$")
CONFIG_NAME_RE = re.compile(r"^[a-z0-9]+(-[a-z0-9]+)*\.json$")


def audit_naming(repo_root: Path, policy_path: Path | None = None) -> JsonMap:
    repo_root = repo_root.resolve()
    policy_path = policy_path or repo_root / "_ops" / "naming" / "naming-policy.json"
    policy = _read_json(policy_path)
    project_registry = _read_json(repo_root / "_ops" / "projects" / "registry.json")
    root_policy = _read_json(repo_root / "_ops" / "projects" / "root-structure-policy.json")

    gaps: list[str] = []
    warnings: list[str] = []
    checked = {
        "root_projects": 0,
        "reserved_operational_dirs": 0,
        "runtime_adapter_dirs": 0,
        "tools": 0,
        "skills": 0,
        "docs": 0,
        "specs": 0,
        "python_source": 0,
        "config_files": 0,
        "config_ids": 0,
    }

    _check_project_names(project_registry, gaps, checked)
    _check_named_items(root_policy.get("reserved_operational_dirs", []), "reserved operational directory", UNDERSCORE_KEBAB_RE, gaps, checked, "reserved_operational_dirs")
    _check_named_items(root_policy.get("runtime_adapter_dirs", []), "runtime adapter directory", DOT_KEBAB_RE, gaps, checked, "runtime_adapter_dirs")
    _check_child_dirs(repo_root / "_tools", "tool folder", KEBAB_RE, gaps, checked, "tools")
    _check_child_dirs(repo_root / "_skills", "skill folder", KEBAB_RE, gaps, checked, "skills")
    _check_docs(repo_root / "_docs", gaps, checked, policy)
    _check_specs(repo_root, project_registry, gaps, checked)
    _check_python_source(repo_root, gaps, checked, policy)
    _check_configs(repo_root, gaps, checked, policy)

    status = "clean" if not gaps else "naming_rework_required"
    return {
        "status": status,
        "requires_rework": bool(gaps),
        "repo_root": str(repo_root),
        "policy_path": str(policy_path),
        "checked": checked,
        "gaps": gaps,
        "warnings": warnings,
        "follow_up_actions": [f"Resolve naming gap: {gap}" for gap in gaps],
    }


def main() -> int:
    parser = argparse.ArgumentParser(description="Audit workspace naming conventions.")
    parser.add_argument("--repo-root", default=".", help="Repository root. Defaults to current directory.")
    parser.add_argument("--policy", default="", help="Optional naming policy JSON path.")
    parser.add_argument("--check", action="store_true", help="Exit with code 1 when naming gaps are found.")
    args = parser.parse_args()

    repo_root = Path(args.repo_root)
    policy = Path(args.policy) if args.policy else None
    report = audit_naming(repo_root, policy)
    print(json.dumps(report, ensure_ascii=False, indent=2))
    return 1 if args.check and report["requires_rework"] else 0


def _check_project_names(registry: JsonMap, gaps: list[str], checked: JsonMap) -> None:
    for project in registry.get("projects", []):
        name = str(project.get("name", "")).strip()
        root = _root_name(str(project.get("path", name)))
        checked["root_projects"] += 1
        if not KEBAB_RE.fullmatch(name):
            gaps.append(f"Project name must be kebab-case: {name}")
        if not KEBAB_RE.fullmatch(root):
            gaps.append(f"Project root path must be kebab-case: {project.get('path')}")
        if name and root and name != root:
            gaps.append(f"Project name and root folder should match: name={name}, root={root}")


def _check_named_items(
    items: list[JsonMap],
    label: str,
    pattern: re.Pattern[str],
    gaps: list[str],
    checked: JsonMap,
    counter: str,
) -> None:
    for item in items:
        name = str(item.get("name", "")).strip()
        checked[counter] += 1
        if not pattern.fullmatch(name):
            gaps.append(f"{label} has invalid name: {name}")


def _check_child_dirs(
    parent: Path,
    label: str,
    pattern: re.Pattern[str],
    gaps: list[str],
    checked: JsonMap,
    counter: str,
) -> None:
    if not parent.exists():
        return
    for path in sorted(parent.iterdir()):
        if not path.is_dir() or path.name.startswith("."):
            continue
        checked[counter] += 1
        if not pattern.fullmatch(path.name):
            gaps.append(f"{label} must be kebab-case: {path.relative_to(parent.parent).as_posix()}")


def _check_docs(docs_root: Path, gaps: list[str], checked: JsonMap, policy: JsonMap) -> None:
    allowed = {item["name"] for item in policy.get("exceptions", [])}
    if not docs_root.exists():
        return
    for path in sorted(docs_root.rglob("*.md")):
        checked["docs"] += 1
        if path.name in allowed:
            continue
        if not DOC_NAME_RE.fullmatch(path.name):
            gaps.append(f"Docs Markdown filename must be lower-kebab with optional language suffix: {path.relative_to(docs_root.parent).as_posix()}")


def _check_specs(repo_root: Path, registry: JsonMap, gaps: list[str], checked: JsonMap) -> None:
    spec_roots = [repo_root / "_specs" / "workspace-platform"]
    for project in registry.get("projects", []):
        spec_roots.append(repo_root / str(project.get("path", "")).strip("/") / "specs")

    for spec_root in spec_roots:
        if not spec_root.exists():
            continue
        for path in sorted(spec_root.iterdir()):
            if not path.is_dir():
                continue
            checked["specs"] += 1
            if not DATE_SLUG_RE.fullmatch(path.name):
                gaps.append(f"Spec directory must use YYYY-MM-DD-lower-kebab: {path.relative_to(repo_root).as_posix()}")


def _check_python_source(repo_root: Path, gaps: list[str], checked: JsonMap, policy: JsonMap) -> None:
    allowed = {item["name"] for item in policy.get("exceptions", [])}
    src_roots = [path for path in repo_root.rglob("src") if path.is_dir() and _is_source_root(path)]

    for src_root in sorted(src_roots):
        for path in sorted(src_root.rglob("*.py")):
            if any(part == "__pycache__" for part in path.parts):
                continue
            checked["python_source"] += 1
            if path.name in allowed:
                continue
            if not SNAKE_RE.fullmatch(path.stem):
                gaps.append(f"Python module filename must be snake_case: {path.relative_to(repo_root).as_posix()}")
        for path in sorted(src_root.rglob("*")):
            if not path.is_dir() or path.name == "__pycache__":
                continue
            checked["python_source"] += 1
            if not SNAKE_RE.fullmatch(path.name):
                gaps.append(f"Python package directory must be snake_case: {path.relative_to(repo_root).as_posix()}")


def _check_configs(repo_root: Path, gaps: list[str], checked: JsonMap, policy: JsonMap) -> None:
    allowed = {item["name"] for item in policy.get("exceptions", [])}
    config_roots = [
        repo_root / "agent-platform" / "configs",
        repo_root / "_ops" / "projects",
        repo_root / "_ops" / "naming",
        repo_root / "_ops" / "assistant-runtimes",
        repo_root / "_ops" / "installations",
    ]
    for config_root in config_roots:
        if not config_root.exists():
            continue
        for path in sorted(config_root.rglob("*.json")):
            checked["config_files"] += 1
            if path.name not in allowed and not CONFIG_NAME_RE.fullmatch(path.name):
                gaps.append(f"Config filename must be lower-kebab: {path.relative_to(repo_root).as_posix()}")
            data = _read_json(path)
            _check_config_identifier(path, "name", data.get("name"), repo_root, gaps, checked)
            _check_config_identifier(path, "id", data.get("id"), repo_root, gaps, checked)


def _check_config_identifier(path: Path, field: str, value: Any, repo_root: Path, gaps: list[str], checked: JsonMap) -> None:
    if value is None:
        return
    checked["config_ids"] += 1
    if not isinstance(value, str) or not KEBAB_RE.fullmatch(value):
        gaps.append(f"Config top-level {field} must be lower-kebab: {path.relative_to(repo_root).as_posix()}")


def _is_source_root(path: Path) -> bool:
    return any(part in {"_tools", "agent-platform", "presentation-agent"} for part in path.parts)


def _root_name(value: str) -> str:
    return value.strip().strip("/").split("/", 1)[0]


def _read_json(path: Path) -> JsonMap:
    return json.loads(path.read_text(encoding="utf-8"))


if __name__ == "__main__":
    raise SystemExit(main())

"""Audit workspace structure against the project boundary policy."""

from __future__ import annotations

import argparse
import fnmatch
import json
from pathlib import Path
from typing import Any


JsonMap = dict[str, Any]


def audit_structure(repo_root: Path, policy_path: Path | None = None) -> JsonMap:
    """Return a deterministic root-structure audit report."""

    repo_root = repo_root.resolve()
    policy_path = policy_path or repo_root / "_ops" / "projects" / "root-structure-policy.json"
    policy = _read_json(policy_path)
    registry = _read_json(repo_root / policy["project_registry_path"])
    gitignore_text = _read_text(repo_root / ".gitignore")

    registered_projects = {
        _normalize_root_name(project.get("path", project.get("name", "")))
        for project in registry.get("projects", [])
    }
    registered_projects.discard("")
    reserved_dirs = {item["name"] for item in policy.get("reserved_operational_dirs", [])}
    local_only_dirs = {item["name"] for item in policy.get("local_only_dirs", [])}
    runtime_adapter_dirs = {item["name"] for item in policy.get("runtime_adapter_dirs", [])}
    generated_output_patterns = [item["pattern"] for item in policy.get("generated_output_dirs", [])]

    root_dirs = sorted(
        path.name
        for path in repo_root.iterdir()
        if path.is_dir() and path.name != ".git"
    )

    gaps: list[str] = []
    warnings: list[str] = []
    classifications = []
    project_inventories = []

    for name in root_dirs:
        classification = _classify_root_dir(
            name,
            registered_projects,
            reserved_dirs,
            local_only_dirs,
            runtime_adapter_dirs,
            generated_output_patterns,
        )
        classifications.append({"name": name, "class": classification})
        if classification == "unknown_root":
            gaps.append(
                f"Root directory '{name}' is neither a registered project, reserved operational folder, local-only folder, runtime adapter folder, nor generated output folder."
            )
        if classification == "local_only" and not _gitignore_mentions(gitignore_text, name):
            gaps.append(f"Local-only root directory '{name}' must be ignored in .gitignore.")

    for project in registry.get("projects", []):
        project_path = repo_root / project.get("path", "")
        if not project_path.exists():
            gaps.append(f"Registered project path does not exist: {project.get('path')}")
            continue
        if not (project_path / "README.md").exists():
            gaps.append(f"Registered project is missing README.md: {project.get('path')}")

    for item in policy.get("local_only_dirs", []):
        name = item["name"]
        if not _gitignore_mentions(gitignore_text, name):
            warnings.append(f"Local-only directory '{name}' is declared but not ignored in .gitignore.")

    for pattern in generated_output_patterns:
        if not _gitignore_mentions_pattern(gitignore_text, pattern):
            gaps.append(f"Generated output pattern '{pattern}' must be ignored in .gitignore.")

    for project in registry.get("projects", []):
        project_path_value = project.get("path", "")
        project_path = repo_root / project_path_value
        if not project_path.exists() or not project_path.is_dir():
            continue

        declared_dirs = _declared_project_top_dirs(project)
        top_dirs = sorted(path.name for path in project_path.iterdir() if path.is_dir())
        generated_dirs = []
        undocumented_dirs = []

        for name in top_dirs:
            if _is_generated_output_name(name, generated_output_patterns):
                generated_dirs.append(name)
                continue
            if name not in declared_dirs:
                undocumented_dirs.append(name)

        for name in undocumented_dirs:
            warnings.append(
                f"Project '{project.get('name', project_path_value)}' has undocumented top-level directory '{name}'. "
                "Add it to project_specific_home or mark it as generated output."
            )

        project_inventories.append(
            {
                "project": project.get("name", _normalize_root_name(project_path_value)),
                "path": project_path_value,
                "declared_top_level_dirs": declared_dirs,
                "actual_top_level_dirs": top_dirs,
                "generated_top_level_dirs": generated_dirs,
                "undocumented_top_level_dirs": undocumented_dirs,
            }
        )

    status = "clean" if not gaps else "structure_rework_required"
    return {
        "status": status,
        "requires_rework": bool(gaps),
        "repo_root": str(repo_root),
        "policy_path": str(policy_path),
        "checks": {
            "root_dirs_count": len(root_dirs),
            "registered_projects_count": len(registered_projects),
            "reserved_dirs_count": len(reserved_dirs),
            "local_only_dirs_count": len(local_only_dirs),
            "runtime_adapter_dirs_count": len(runtime_adapter_dirs),
            "generated_output_patterns_count": len(generated_output_patterns),
            "project_inventories_count": len(project_inventories),
        },
        "classifications": classifications,
        "project_inventories": project_inventories,
        "gaps": gaps,
        "warnings": warnings,
        "follow_up_actions": [f"Resolve structure gap: {gap}" for gap in gaps],
    }


def main() -> int:
    parser = argparse.ArgumentParser(description="Audit root-level workspace structure.")
    parser.add_argument("--repo-root", default=".", help="Repository root. Defaults to current directory.")
    parser.add_argument("--policy", default="", help="Optional policy JSON path.")
    parser.add_argument("--check", action="store_true", help="Exit with code 1 when gaps are found.")
    args = parser.parse_args()

    repo_root = Path(args.repo_root)
    policy = Path(args.policy) if args.policy else None
    report = audit_structure(repo_root, policy)
    print(json.dumps(report, ensure_ascii=False, indent=2))
    return 1 if args.check and report["requires_rework"] else 0


def _classify_root_dir(
    name: str,
    registered_projects: set[str],
    reserved_dirs: set[str],
    local_only_dirs: set[str],
    runtime_adapter_dirs: set[str],
    generated_output_patterns: list[str],
) -> str:
    if name in registered_projects:
        return "registered_project"
    if name in reserved_dirs:
        return "reserved_operational"
    if name in local_only_dirs:
        return "local_only"
    if name in runtime_adapter_dirs:
        return "runtime_adapter"
    if _is_generated_output_name(name, generated_output_patterns):
        return "generated_output"
    return "unknown_root"


def _normalize_root_name(value: str) -> str:
    return value.strip().strip("/").split("/", 1)[0]


def _gitignore_mentions(gitignore_text: str, name: str) -> bool:
    candidates = {name, f"{name}/", f"/{name}", f"/{name}/"}
    lines = {line.strip() for line in gitignore_text.splitlines() if line.strip() and not line.strip().startswith("#")}
    return bool(candidates.intersection(lines))


def _gitignore_mentions_pattern(gitignore_text: str, pattern: str) -> bool:
    lines = {line.strip() for line in gitignore_text.splitlines() if line.strip() and not line.strip().startswith("#")}
    normalized = pattern.strip()
    suffix = normalized.removeprefix("**/").strip("/")
    basename = suffix.rsplit("/", 1)[-1]
    candidates = {
        normalized,
        normalized.strip("/"),
        suffix,
        f"{suffix}/",
        f"/{suffix}/",
        basename,
        f"{basename}/",
        f"/{basename}/",
    }
    wildcard_suffix = Path(basename).suffix
    if wildcard_suffix:
        candidates.add(f"*{wildcard_suffix}")
    return bool(candidates.intersection(lines))


def _declared_project_top_dirs(project: JsonMap) -> list[str]:
    project_root = _normalize_root_name(project.get("path", project.get("name", "")))
    declared = set()
    for value in project.get("project_specific_home", []):
        path = value.strip().strip("/")
        if not path:
            continue
        if path == project_root:
            continue
        if path.startswith(f"{project_root}/"):
            path = path[len(project_root) + 1 :]
        declared.add(path.split("/", 1)[0])
    return sorted(declared)


def _is_generated_output_name(name: str, patterns: list[str]) -> bool:
    candidates = {name, f"{name}/"}
    for pattern in patterns:
        suffix = pattern.removeprefix("**/").strip("/")
        basename = suffix.rsplit("/", 1)[-1]
        pattern_candidates = {suffix, f"{suffix}/", basename, f"{basename}/"}
        if candidates.intersection(pattern_candidates):
            return True
        if any(fnmatch.fnmatch(candidate, pattern.removeprefix("**/")) for candidate in candidates):
            return True
    return False


def _read_json(path: Path) -> JsonMap:
    return json.loads(path.read_text(encoding="utf-8"))


def _read_text(path: Path) -> str:
    return path.read_text(encoding="utf-8") if path.exists() else ""


if __name__ == "__main__":
    raise SystemExit(main())

from __future__ import annotations

import argparse
import html
import json
import sys
from datetime import datetime
from pathlib import Path
from typing import Any


JsonMap = dict[str, Any]


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Generate coordination boards.")
    parser.add_argument("--root", type=Path, default=Path(__file__).resolve().parents[3])
    parser.add_argument("--check", action="store_true", help="Fail if generated boards are stale.")
    args = parser.parse_args(argv)

    root = args.root.resolve()
    status_path = root / "_ops" / "coordination" / "status.json"
    status = load_status(status_path)

    outputs = {
        root / "_ops" / "coordination" / "board.ko.md": render_markdown(status, "ko", root),
        root / "_ops" / "coordination" / "board.en.md": render_markdown(status, "en", root),
        root / "_ops" / "coordination" / "board.html": render_html(status, root),
    }

    stale = []
    for path, content in outputs.items():
        normalized = content.rstrip() + "\n"
        if args.check:
            if not path.exists() or path.read_text(encoding="utf-8") != normalized:
                stale.append(path)
            continue
        path.write_text(normalized, encoding="utf-8")
        print(f"updated: {path.relative_to(root)}")

    if stale:
        for path in stale:
            print(f"stale: {path.relative_to(root)}", file=sys.stderr)
        return 1
    return 0


def load_status(path: Path) -> JsonMap:
    with path.open("r", encoding="utf-8") as file:
        data = json.load(file)
    validate_status(data)
    return data


def validate_status(data: JsonMap) -> None:
    for key in ("updated_at", "summary", "agents", "tasks"):
        if key not in data:
            raise ValueError(f"status.json missing required key: {key}")
    if not isinstance(data["agents"], list):
        raise TypeError("agents must be a list")
    if not isinstance(data["tasks"], list):
        raise TypeError("tasks must be a list")


def render_markdown(status: JsonMap, language: str, root: Path) -> str:
    ko = language == "ko"
    labels = {
        "title": "작업 조율 보드" if ko else "Work Coordination Board",
        "generated": "생성 위치" if ko else "Generated from",
        "updated": "마지막 갱신" if ko else "Last updated",
        "summary": "요약" if ko else "Summary",
        "agents": "에이전트" if ko else "Agents",
        "tasks": "작업" if ko else "Tasks",
        "blockers": "차단 요소" if ko else "Blockers",
    }

    lines = [
        f"# {labels['title']}",
        "",
        f"- {labels['generated']}: `_ops/coordination/status.json`",
        f"- {labels['updated']}: `{status['updated_at']}`",
        f"- {labels['summary']}: {status['summary']}",
        "",
        f"## {labels['agents']}",
        "",
        "| ID | Name | Role | Status | Current Task |",
        "| --- | --- | --- | --- | --- |",
    ]

    for agent in status["agents"]:
        lines.append(
            "| {id} | {name} | {role} | {status} | {current_task} |".format(
                id=md(agent.get("id", "")),
                name=md(agent.get("name", "")),
                role=md(agent.get("role", "")),
                status=md(agent.get("status", "")),
                current_task=md(agent.get("current_task", "")),
            )
        )

    lines.extend(
        [
            "",
            f"## {labels['tasks']}",
            "",
            "| ID | Title | Project | Status | Agent | Timing | Bottleneck | Next Action |",
            "| --- | --- | --- | --- | --- | --- | --- | --- |",
        ]
    )
    for task in status["tasks"]:
        timing = timing_summary_for_task(task, root)
        lines.append(
            "| {id} | {title} | {project} | {status} | {agent} | {timing} | {bottleneck} | {next_action} |".format(
                id=md(task.get("id", "")),
                title=md(task.get("title", "")),
                project=md(task.get("project", "")),
                status=md(task.get("status", "")),
                agent=md(task.get("agent", "")),
                timing=md(timing["timing"]),
                bottleneck=md(timing["bottleneck"]),
                next_action=md(task.get("next_action", "")),
            )
        )

    lines.extend(["", f"## {labels['blockers']}", ""])
    blockers = [(task.get("id", ""), blocker) for task in status["tasks"] for blocker in task.get("blockers", [])]
    if blockers:
        for task_id, blocker in blockers:
            lines.append(f"- `{task_id}`: {blocker}")
    else:
        lines.append("- None")

    return "\n".join(lines)


