            status=_optional_string(data.get("status", "missing"), "status"),
            evidence=_tuple_of_strings(data.get("evidence", []), "evidence"),
            rationale=_optional_string(data.get("rationale", ""), "rationale"),
        )


@dataclass(frozen=True)
