            resource_risks=_tuple_from_objects(data.get("resource_risks", []), "resource_risks", ResourceRisk.from_dict),
            lifecycle_checks=_tuple_from_objects(
                data.get("lifecycle_checks", []),
                "lifecycle_checks",
                LifecycleCheck.from_dict,
            ),
