            ),
            notes=_tuple_of_strings(data.get("notes", []), "notes"),
        )


def check_resource_leaks(guard_input: ResourceGuardInput) -> JsonMap:
    """Return a deterministic resource leak readiness report."""

    gaps: list[str] = []
    warnings: list[str] = []

    if not guard_input.task.strip():
        gaps.append("Task is missing.")
    if not guard_input.runtime_context:
        warnings.append("runtime_context is empty. Record runtimes such as python, node, nextjs, playwright, browser, server, worker, or cli.")
    if not guard_input.resource_risks:
        gaps.append("resource_risks is empty. List memory, process, browser, cache, worker, stream, or large-data risks for this task.")

    for risk in guard_input.resource_risks:
        _check_resource_risk(risk, gaps, warnings)
    for lifecycle in guard_input.lifecycle_checks:
        _check_lifecycle(lifecycle, gaps, warnings)
    for measurement in guard_input.measurement_checks:
        _check_measurement(measurement, gaps, warnings)

    requires_rework = bool(gaps)
    status = "rework_required" if requires_rework else "resource_ready"

    return {
        "status": status,
        "requires_rework": requires_rework,
        "work_mode": guard_input.work_mode,
        "resource_summary": {
            "runtime_context_count": len(guard_input.runtime_context),
            "resource_risks_count": len(guard_input.resource_risks),
            "lifecycle_checks_count": len(guard_input.lifecycle_checks),
            "measurement_checks_count": len(guard_input.measurement_checks),
        },
        "gaps": gaps,
        "warnings": warnings,
        "follow_up_actions": [f"Resolve resource gap: {gap}" for gap in gaps],
    }


def _check_resource_risk(risk: ResourceRisk, gaps: list[str], warnings: list[str]) -> None:
    label = risk.risk_id or risk.description or "<unnamed-risk>"
    if not risk.risk_id.strip():
        gaps.append("Resource risk is missing risk_id.")
    if risk.category not in RISK_CATEGORIES:
        gaps.append(f"Resource risk {label} has invalid category '{risk.category}'.")
    if not risk.description.strip():
        gaps.append(f"Resource risk {label} is missing description.")
    if risk.status not in RISK_STATUSES:
        gaps.append(f"Resource risk {label} has invalid status '{risk.status}'.")
        return

    if risk.required and risk.status == "unresolved":
        gaps.append(f"Required resource risk {label} is unresolved.")
    if risk.status == "mitigated":
        if risk.required and not risk.mitigation.strip():
            gaps.append(f"Required resource risk {label} is mitigated but has no mitigation.")
        if risk.required and not risk.evidence:
            gaps.append(f"Required resource risk {label} is mitigated but has no evidence.")
    if risk.status in {"accepted", "not_applicable"} and not risk.rationale.strip():
        gaps.append(f"Resource risk {label} is {risk.status} without rationale.")
    if not risk.required and risk.status == "unresolved":
        warnings.append(f"Optional resource risk {label} is unresolved.")


def _check_lifecycle(check: LifecycleCheck, gaps: list[str], warnings: list[str]) -> None:
    label = check.check_id or check.resource or "<unnamed-lifecycle>"
    if not check.check_id.strip():
        gaps.append("Lifecycle check is missing check_id.")
    if not check.resource.strip():
        gaps.append(f"Lifecycle check {label} is missing resource.")
    if not check.create_path.strip():
        gaps.append(f"Lifecycle check {label} is missing create_path.")
    if check.required and not check.cleanup_path.strip():
        gaps.append(f"Required lifecycle check {label} is missing cleanup_path.")
    if check.status not in CHECK_STATUSES:
        gaps.append(f"Lifecycle check {label} has invalid status '{check.status}'.")
        return

    _check_required_status("Lifecycle check", label, check.required, check.status, check.evidence, check.rationale, gaps, warnings)


def _check_measurement(check: MeasurementCheck, gaps: list[str], warnings: list[str]) -> None:
    label = check.check_id or check.metric or "<unnamed-measurement>"
    if not check.check_id.strip():
        gaps.append("Measurement check is missing check_id.")
    if not check.metric.strip():
        gaps.append(f"Measurement check {label} is missing metric.")
    if not check.tool.strip():
        gaps.append(f"Measurement check {label} is missing tool.")
    if check.required and not check.threshold.strip():
        gaps.append(f"Required measurement check {label} is missing threshold.")
    if check.status not in CHECK_STATUSES:
        gaps.append(f"Measurement check {label} has invalid status '{check.status}'.")
        return

    _check_required_status("Measurement check", label, check.required, check.status, check.evidence, check.rationale, gaps, warnings)


def _check_required_status(
    noun: str,
    label: str,
    required: bool,
    status: str,
    evidence: tuple[str, ...],
    rationale: str,
    gaps: list[str],
    warnings: list[str],
) -> None:
    if required and status == "passed" and not evidence:
        gaps.append(f"Required {noun.lower()} {label} passed but has no evidence.")
    if required and status in {"failed", "not_run"}:
        gaps.append(f"Required {noun.lower()} {label} status is {status}.")
    if status in {"deferred", "not_applicable"} and not rationale.strip():
        gaps.append(f"{noun} {label} is {status} without rationale.")
    if not required and status in {"failed", "not_run"}:
        warnings.append(f"Optional {noun.lower()} {label} status is {status}.")


def _required_string(data: JsonMap, field_name: str) -> str:
    value = data.get(field_name)
    if not isinstance(value, str):
        raise TypeError(f"{field_name} must be a string.")
    return value


def _optional_string(value: Any, field_name: str) -> str:
    if not isinstance(value, str):
        raise TypeError(f"{field_name} must be a string.")
    return value


def _optional_bool(value: Any, field_name: str) -> bool:
    if not isinstance(value, bool):
        raise TypeError(f"{field_name} must be a bool.")
    return value


def _tuple_of_strings(value: Any, field_name: str) -> tuple[str, ...]:
    if not isinstance(value, list | tuple):
        raise TypeError(f"{field_name} must be a list of strings.")
    if not all(isinstance(item, str) for item in value):
        raise TypeError(f"{field_name} must contain only strings.")
    return tuple(value)


def _tuple_from_objects(value: Any, field_name: str, factory: Any) -> tuple[Any, ...]:
    if not isinstance(value, list | tuple):
        raise TypeError(f"{field_name} must be a list of objects.")
    if not all(isinstance(item, dict) for item in value):
        raise TypeError(f"{field_name} must contain only objects.")
    return tuple(factory(item) for item in value)

"""Check whether repository skills are installed and trigger-ready."""

from __future__ import annotations

import hashlib
import json
import re
from pathlib import Path
from typing import Any


JsonMap = dict[str, Any]


def load_skill_activation_registry(path: Path) -> JsonMap:
    """Load a skill activation registry."""

    with path.open("r", encoding="utf-8") as file:
        return json.load(file)


def check_skill_activation(config: JsonMap, repo_root: Path) -> JsonMap:
    """Check source, install, trigger, and drift status for custom skills."""

    gaps: list[str] = []
    warnings: list[str] = []
    skills = config.get("skills")
    if not isinstance(skills, list) or not skills:
        gaps.append("skills must be a non-empty list.")
        skills = []

    installed_ready = 0
    source_ready = 0
    trigger_ready = 0
    drift_free = 0

    for index, skill in enumerate(skills, start=1):
        label = f"skills[{index}]"
        if not isinstance(skill, dict):
            gaps.append(f"{label} must be an object.")
            continue

        name = _required_string(skill, "name", label, gaps)
        source_path_text = _required_string(skill, "source_path", label, gaps)
        installed_path_text = _required_string(skill, "installed_path", label, gaps)
        auto_expected = skill.get("auto_activation_expected")
        if not isinstance(auto_expected, bool):
            gaps.append(f"{label}.auto_activation_expected must be a bool.")
            auto_expected = False

        trigger_examples = _string_list(skill.get("trigger_examples"), f"{label}.trigger_examples", gaps)
        if len(trigger_examples) >= 2:
            trigger_ready += 1
        else:
            gaps.append(f"{label}.trigger_examples must include at least two realistic trigger prompts.")

        _string_list(skill.get("negative_examples"), f"{label}.negative_examples", warnings, required=False)
        sync_files = _string_list(skill.get("sync_files"), f"{label}.sync_files", gaps)

        source_path = _resolve_path(source_path_text, repo_root)
        installed_path = _resolve_path(installed_path_text, repo_root)
        source_skill_md = source_path / "SKILL.md"
        installed_skill_md = installed_path / "SKILL.md"

        if not source_path.exists():
            gaps.append(f"{label}.source_path does not exist: {source_path_text}.")
            continue
        if not source_skill_md.exists():
            gaps.append(f"{label}.source_path is missing SKILL.md: {source_path_text}.")
            continue

        source_ready += 1
        frontmatter, parse_gap = _parse_frontmatter(source_skill_md.read_text(encoding="utf-8"))
        if parse_gap:
            gaps.append(f"{label}.SKILL.md {parse_gap}")
        else:
            _check_frontmatter(name, frontmatter, label, gaps)

        if auto_expected:
            if not installed_path.exists():
                gaps.append(f"{label}.installed_path missing for auto activation: {installed_path_text}.")
                continue
            if not installed_skill_md.exists():
                gaps.append(f"{label}.installed_path is missing SKILL.md: {installed_path_text}.")
                continue
            installed_ready += 1
            if _paths_match(source_path, installed_path, sync_files, warnings, label):
                drift_free += 1
            else:
                gaps.append(f"{label} installed copy is not in sync with source for one or more sync_files.")
        else:
            warnings.append(f"{label} is source-only; it will not auto-trigger unless explicitly installed or named.")

    status = "activation_ready" if not gaps else "activation_rework_required"
    return {
        "status": status,
        "requires_rework": bool(gaps),
        "principle": (
            "A repository skill is not automatically useful until its source is valid, "
            "its trigger examples are clear, its installed Codex copy exists when auto activation is expected, "
            "and the installed copy has not drifted from source."
        ),
        "checks": {
            "skills_count": len(skills),
            "source_ready_count": source_ready,
            "installed_ready_count": installed_ready,
            "trigger_ready_count": trigger_ready,
            "drift_free_count": drift_free,
        },
        "gaps": gaps,
        "warnings": warnings,
        "follow_up_actions": [f"Resolve skill activation gap: {gap}" for gap in gaps]
        + [f"Consider skill activation warning: {warning}" for warning in warnings],
    }


def _resolve_path(path_text: str, repo_root: Path) -> Path:
    path = Path(path_text).expanduser()
    return path if path.is_absolute() else repo_root / path


def _parse_frontmatter(content: str) -> tuple[dict[str, str], str]:
    if not content.startswith("---"):
        return {}, "frontmatter is missing."
    match = re.match(r"^---\n(.*?)\n---\n?", content, re.DOTALL)
    if not match:
        return {}, "frontmatter format is invalid."
    frontmatter: dict[str, str] = {}
    for line in match.group(1).splitlines():
        if not line.strip():
            continue
        if ":" not in line:
            return {}, f"frontmatter line is invalid: {line}."
        key, value = line.split(":", 1)
        frontmatter[key.strip()] = value.strip().strip('"').strip("'")
    return frontmatter, ""


def _check_frontmatter(expected_name: str, frontmatter: dict[str, str], label: str, gaps: list[str]) -> None:
    name = frontmatter.get("name", "").strip()
    description = frontmatter.get("description", "").strip()
    if name != expected_name:
        gaps.append(f"{label}.SKILL.md frontmatter name must match registry name: {expected_name}.")
    if len(description) < 80:
        gaps.append(f"{label}.SKILL.md description is too short for reliable automatic triggering.")
    lowered = description.lower()
    if "use when" not in lowered and "use for" not in lowered:
        gaps.append(f"{label}.SKILL.md description must include 'Use when' or 'Use for'.")


def _paths_match(source_path: Path, installed_path: Path, sync_files: list[str], warnings: list[str], label: str) -> bool:
    matched = True
    for relative in sync_files:
        source_file = source_path / relative
        installed_file = installed_path / relative
        if not source_file.exists():
            warnings.append(f"{label}.sync_files item missing from source: {relative}.")
            matched = False
            continue
        if not installed_file.exists():
            warnings.append(f"{label}.sync_files item missing from installed copy: {relative}.")
            matched = False
            continue
        if _sha256(source_file) != _sha256(installed_file):
            warnings.append(f"{label}.sync_files item differs between source and installed copy: {relative}.")
            matched = False
    return matched


def _sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as file:
        for chunk in iter(lambda: file.read(65536), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _required_string(source: JsonMap, field_name: str, label: str, gaps: list[str]) -> str:
    value = source.get(field_name)
    if not isinstance(value, str) or not value.strip():
        gaps.append(f"{label}.{field_name} must be a non-empty string.")
        return ""
    return value.strip()


def _string_list(value: Any, label: str, gaps: list[str], required: bool = True) -> list[str]:
    if value is None and not required:
        return []
    if not isinstance(value, list) or (required and not value):
        gaps.append(f"{label} must be a non-empty list.")
        return []
    result: list[str] = []
    for index, item in enumerate(value, start=1):
        if not isinstance(item, str) or not item.strip():
            gaps.append(f"{label}[{index}] must be a non-empty string.")
            continue
        result.append(item.strip())
    return result

"""Validate repository-managed Codex skill source folders."""

from __future__ import annotations

import re
from dataclasses import dataclass
from pathlib import Path
from typing import Any


JsonMap = dict[str, Any]

MAX_SKILL_NAME_LENGTH = 64
MAX_SKILL_MD_LINES = 500
DISALLOWED_SKILL_DOCS = {
    "README.md",
    "INSTALLATION_GUIDE.md",
    "QUICK_REFERENCE.md",
    "CHANGELOG.md",
}


@dataclass(frozen=True)
class SkillValidationInput:
    """Input for validating a custom skill before close-out or installation."""

    skill_path: str
    intended_use: str
    trigger_examples: tuple[str, ...] = ()
    validation_steps: tuple[str, ...] = ()
    forward_test_scenarios: tuple[str, ...] = ()
    improvement_ideas: tuple[str, ...] = ()
    known_gaps: tuple[str, ...] = ()

    @classmethod
    def from_dict(cls, data: JsonMap) -> "SkillValidationInput":
        return cls(
            skill_path=_required_string(data, "skill_path"),
            intended_use=_required_string(data, "intended_use"),
            trigger_examples=_tuple_of_strings(data.get("trigger_examples", []), "trigger_examples"),
            validation_steps=_tuple_of_strings(data.get("validation_steps", []), "validation_steps"),
            forward_test_scenarios=_tuple_of_strings(data.get("forward_test_scenarios", []), "forward_test_scenarios"),
            improvement_ideas=_tuple_of_strings(data.get("improvement_ideas", []), "improvement_ideas"),
            known_gaps=_tuple_of_strings(data.get("known_gaps", []), "known_gaps"),
        )


def validate_skill_definition(validation_input: SkillValidationInput, repo_root: Path | None = None) -> JsonMap:
    """Return a deterministic validation report for a skill source folder."""

    root = repo_root if repo_root is not None else Path.cwd()
    skill_path = Path(validation_input.skill_path)
    if not skill_path.is_absolute():
        skill_path = root / skill_path
    skill_path = skill_path.resolve()

    gaps = list(validation_input.known_gaps)
    warnings: list[str] = []

    if not validation_input.skill_path.strip():
        gaps.append("Skill path is missing.")
    if not validation_input.intended_use.strip():
        gaps.append("Intended use is missing.")
    if len(validation_input.trigger_examples) < 2:
        gaps.append("At least two trigger examples are required.")
    if not validation_input.validation_steps:
        gaps.append("Validation steps are missing.")
    if not validation_input.forward_test_scenarios:
        gaps.append("Forward-test scenarios are missing.")
    if not validation_input.improvement_ideas:
        warnings.append("Improvement ideas are missing; record at least one next improvement or explain that none were found.")

    if not skill_path.exists() or not skill_path.is_dir():
        gaps.append(f"Skill folder does not exist: {validation_input.skill_path}.")
        return _report(validation_input, gaps, warnings, skill_path, {}, 0)

    try:
        relative_path = skill_path.relative_to(root.resolve())
    except ValueError:
        relative_path = skill_path

    relative_path_text = str(relative_path)
    if not (relative_path_text.startswith("_skills/") or "/skills/" in relative_path_text):
        gaps.append("Skill source should live under _skills/<skill-name>/ or the owning project's skills/ folder.")

    skill_md = skill_path / "SKILL.md"
    if not skill_md.exists():
        gaps.append("SKILL.md is missing.")
        return _report(validation_input, gaps, warnings, skill_path, {}, 0)

    content = skill_md.read_text(encoding="utf-8")
    frontmatter, body, parse_gap = _parse_frontmatter(content)
    if parse_gap:
        gaps.append(parse_gap)
    else:
        gaps.extend(_validate_frontmatter(frontmatter, skill_path.name))
        gaps.extend(_validate_body(body))
        warnings.extend(_body_warnings(body))

    disallowed = sorted(path.name for path in skill_path.iterdir() if path.name in DISALLOWED_SKILL_DOCS)
    if disallowed:
        gaps.append(f"Skill folder contains non-skill documentation files: {', '.join(disallowed)}.")

    line_count = len(content.splitlines())
    if line_count > MAX_SKILL_MD_LINES:
        gaps.append(f"SKILL.md is too long ({line_count} lines). Keep it under {MAX_SKILL_MD_LINES} lines and move detail to references/.")

    if not (skill_path / "agents" / "openai.yaml").exists():
        warnings.append("agents/openai.yaml is missing; add UI metadata unless the skill is intentionally source-only.")

    return _report(validation_input, gaps, warnings, skill_path, frontmatter, line_count)


def _report(
    validation_input: SkillValidationInput,
    gaps: list[str],
    warnings: list[str],
    skill_path: Path,
    frontmatter: dict[str, str],
    line_count: int,
) -> JsonMap:
    status = "rework_required" if gaps else "skill_ready"
    return {
        "status": status,
        "requires_rework": bool(gaps),
        "principle": "Skills are reusable capabilities and must include trigger clarity, validation, forward-testing, and an improvement loop.",
        "checks": {
            "skill_path": str(skill_path),
            "frontmatter_name": frontmatter.get("name", ""),
            "description_present": bool(frontmatter.get("description", "").strip()),
            "skill_md_line_count": line_count,
            "trigger_examples_count": len(validation_input.trigger_examples),
            "validation_steps_count": len(validation_input.validation_steps),
            "forward_test_scenarios_count": len(validation_input.forward_test_scenarios),
            "improvement_ideas_count": len(validation_input.improvement_ideas),
        },
        "gaps": gaps,
        "warnings": warnings,
        "follow_up_actions": [f"Resolve skill gap: {gap}" for gap in gaps]
        + [f"Consider skill improvement: {warning}" for warning in warnings],
    }


def _parse_frontmatter(content: str) -> tuple[dict[str, str], str, str]:
    if not content.startswith("---"):
        return {}, "", "SKILL.md frontmatter is missing."
    match = re.match(r"^---\n(.*?)\n---\n?(.*)$", content, re.DOTALL)
    if not match:
        return {}, "", "SKILL.md frontmatter format is invalid."
    frontmatter: dict[str, str] = {}
    for line in match.group(1).splitlines():
        if not line.strip():
            continue
        if ":" not in line:
            return {}, "", f"Invalid frontmatter line: {line}."
        key, value = line.split(":", 1)
        frontmatter[key.strip()] = value.strip().strip('"').strip("'")
    return frontmatter, match.group(2), ""


def _validate_frontmatter(frontmatter: dict[str, str], folder_name: str) -> list[str]:
    gaps = []
    unexpected = set(frontmatter) - {"name", "description"}
    if unexpected:
        gaps.append(f"Unexpected SKILL.md frontmatter keys: {', '.join(sorted(unexpected))}.")
    name = frontmatter.get("name", "").strip()
    description = frontmatter.get("description", "").strip()
    if not name:
        gaps.append("Frontmatter name is missing.")
    elif not re.match(r"^[a-z0-9-]+$", name):
        gaps.append("Frontmatter name must use lowercase hyphen-case.")
    elif name.startswith("-") or name.endswith("-") or "--" in name:
        gaps.append("Frontmatter name cannot start/end with hyphen or contain consecutive hyphens.")
    elif len(name) > MAX_SKILL_NAME_LENGTH:
        gaps.append(f"Frontmatter name is too long; maximum is {MAX_SKILL_NAME_LENGTH} characters.")
    elif name != folder_name:
        gaps.append("Frontmatter name must match the skill folder name.")

    if not description:
        gaps.append("Frontmatter description is missing.")
    elif "[TODO" in description or "TODO" in description:
        gaps.append("Frontmatter description still contains TODO text.")
    else:
        if len(description) < 80:
            gaps.append("Frontmatter description is too short to reliably trigger the skill.")
        if "when" not in description.lower() and "use for" not in description.lower():
            gaps.append("Frontmatter description must include when to use the skill.")
    return gaps


def _validate_body(body: str) -> list[str]:
    gaps = []
    stripped = body.strip()
    if not stripped:
        gaps.append("SKILL.md body is missing.")
    if "TODO" in body:
        gaps.append("SKILL.md body still contains TODO text.")
    return gaps


def _body_warnings(body: str) -> list[str]:
    warnings = []
    if "validation" not in body.lower() and "validate" not in body.lower():
        warnings.append("SKILL.md should mention how the skill is validated.")
    if "forward" not in body.lower() and "test" not in body.lower():
        warnings.append("SKILL.md should mention forward-testing or realistic usage tests.")
    return warnings


def _required_string(data: JsonMap, field_name: str) -> str:
    value = data.get(field_name)
    if not isinstance(value, str):
        raise TypeError(f"{field_name} must be a string.")
    return value


def _tuple_of_strings(value: Any, field_name: str) -> tuple[str, ...]:
    if not isinstance(value, list | tuple):
        raise TypeError(f"{field_name} must be a list of strings.")
    if not all(isinstance(item, str) for item in value):
        raise TypeError(f"{field_name} must contain only strings.")
    return tuple(value)

"""Validate that shared JSON config files are self-documenting."""

from __future__ import annotations

from typing import Any


JsonMap = dict[str, Any]

REQUIRED_TOP_LEVEL_FIELDS = {
    "schema_version",
    "name",
    "purpose",
    "reader_guide",
    "reference_links",
    "structure_rules",
    "field_guide",
}

REQUIRED_READER_GUIDE_FIELDS = {"summary", "how_to_read", "owner", "last_reviewed", "update_triggers"}
REQUIRED_REFERENCE_FIELDS = {"id", "title", "source_type", "used_for", "last_checked"}
REQUIRED_STRUCTURE_RULE_FIELDS = {"id", "rule", "reason", "applies_to"}
REQUIRED_FIELD_GUIDE_FIELDS = {"field", "meaning", "required"}


def check_config_contract(config: JsonMap, path: str = "") -> JsonMap:
    """Return whether a settings file explains its references and structure in-place."""

    gaps: list[str] = []
    warnings: list[str] = []
    label = path or _optional_string(config.get("name", "config"), "name")

    missing_top_fields = sorted(REQUIRED_TOP_LEVEL_FIELDS - set(config))
    if missing_top_fields:
        gaps.append(f"{label}: missing top-level self-documenting fields: {', '.join(missing_top_fields)}.")

    _check_reader_guide(config.get("reader_guide"), label, gaps)
    _check_reference_links(config.get("reference_links"), label, gaps, warnings)
    _check_structure_rules(config.get("structure_rules"), label, gaps)
    _check_field_guide(config.get("field_guide"), label, gaps)

    status = "self_documenting" if not gaps else "documentation_contract_required"

    return {
        "status": status,
        "requires_rework": bool(gaps),
        "principle": "A shared config file must explain its purpose, references, structure rules, and important fields inside the file itself.",
        "checks": {
            "top_level_fields_count": len(config),
            "reference_links_count": _safe_len(config.get("reference_links")),
            "structure_rules_count": _safe_len(config.get("structure_rules")),
            "field_guide_count": _safe_len(config.get("field_guide")),
        },
        "gaps": gaps,
        "warnings": warnings,
        "follow_up_actions": [f"Resolve config contract gap: {gap}" for gap in gaps],
    }


def _check_reader_guide(value: Any, label: str, gaps: list[str]) -> None:
    if not isinstance(value, dict):
        gaps.append(f"{label}: reader_guide must be an object.")
        return
    missing = sorted(REQUIRED_READER_GUIDE_FIELDS - set(value))
    if missing:
        gaps.append(f"{label}: reader_guide missing fields: {', '.join(missing)}.")
    if not _non_empty_string(value.get("summary")):
        gaps.append(f"{label}: reader_guide.summary must explain the config in plain language.")
    if not _list_of_non_empty_strings(value.get("how_to_read")):
        gaps.append(f"{label}: reader_guide.how_to_read must list how a human or agent should read this file.")
    if not _list_of_non_empty_strings(value.get("update_triggers")):
        gaps.append(f"{label}: reader_guide.update_triggers must list when to update this file.")


def _check_reference_links(value: Any, label: str, gaps: list[str], warnings: list[str]) -> None:
    if not isinstance(value, list) or not value:
        gaps.append(f"{label}: reference_links must be a non-empty list.")
        return

    for index, item in enumerate(value, start=1):
        item_label = f"{label}: reference_links[{index}]"
        if not isinstance(item, dict):
            gaps.append(f"{item_label} must be an object.")
            continue
        missing = sorted(REQUIRED_REFERENCE_FIELDS - set(item))
        if missing:
            gaps.append(f"{item_label} missing fields: {', '.join(missing)}.")
        if not (_non_empty_string(item.get("url")) or _non_empty_string(item.get("path"))):
            gaps.append(f"{item_label} must include url or path.")
        if not _list_of_non_empty_strings(item.get("used_for")):
            gaps.append(f"{item_label}.used_for must be a non-empty list.")
        if _non_empty_string(item.get("url")) and not _non_empty_string(item.get("last_checked")):
            gaps.append(f"{item_label} external URL needs last_checked.")
        if item.get("source_type") == "social":
            warnings.append(f"{item_label} is a social source; use it as discovery or adoption signal, not proof.")


def _check_structure_rules(value: Any, label: str, gaps: list[str]) -> None:
    if not isinstance(value, list) or not value:
        gaps.append(f"{label}: structure_rules must be a non-empty list.")
        return

    for index, item in enumerate(value, start=1):
        item_label = f"{label}: structure_rules[{index}]"
        if not isinstance(item, dict):
            gaps.append(f"{item_label} must be an object.")
            continue
        missing = sorted(REQUIRED_STRUCTURE_RULE_FIELDS - set(item))
        if missing:
            gaps.append(f"{item_label} missing fields: {', '.join(missing)}.")
        if not _non_empty_string(item.get("rule")):
            gaps.append(f"{item_label}.rule must be non-empty.")


def _check_field_guide(value: Any, label: str, gaps: list[str]) -> None:
    if not isinstance(value, list) or not value:
        gaps.append(f"{label}: field_guide must be a non-empty list.")
        return

    fields_seen = set()
    for index, item in enumerate(value, start=1):
        item_label = f"{label}: field_guide[{index}]"
        if not isinstance(item, dict):
            gaps.append(f"{item_label} must be an object.")
            continue
        missing = sorted(REQUIRED_FIELD_GUIDE_FIELDS - set(item))
        if missing:
            gaps.append(f"{item_label} missing fields: {', '.join(missing)}.")
        field_name = item.get("field")
        if not _non_empty_string(field_name):
            gaps.append(f"{item_label}.field must be non-empty.")
        elif field_name in fields_seen:
            gaps.append(f"{item_label}.field is duplicated: {field_name}.")
        else:
            fields_seen.add(field_name)
        if not _non_empty_string(item.get("meaning")):
            gaps.append(f"{item_label}.meaning must be non-empty.")
        if not isinstance(item.get("required"), bool):
            gaps.append(f"{item_label}.required must be a bool.")


def _non_empty_string(value: Any) -> bool:
    return isinstance(value, str) and bool(value.strip())


def _list_of_non_empty_strings(value: Any) -> bool:
    return isinstance(value, list) and bool(value) and all(_non_empty_string(item) for item in value)


def _safe_len(value: Any) -> int:
    return len(value) if isinstance(value, list) else 0


def _optional_string(value: Any, field_name: str) -> str:
    if not isinstance(value, str):
        raise TypeError(f"{field_name} must be a string.")
    return value

"""Validate structural guardrail composition records."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any


JsonMap = dict[str, Any]

RISK_CATEGORIES = {
    "security",
    "privacy",
    "cost",
    "publication",
    "deployment",
    "destructive_change",
    "external_tool_call",
    "file_access",
    "permission",
    "high_stakes_claim",
    "other",
