IMPACT_LEVELS = {"low", "medium", "high"}
REVERSIBILITY_LEVELS = {"reversible", "partially_reversible", "irreversible"}

GUARDRAIL_TYPES = {
    "input_filter_or_redaction",
    "output_schema_or_format_contract",
