    "human_checkpoint_or_arbitration",
    "privacy_or_security_audit",
    "rollback_or_recovery_gate",
}

ACTION_SIDE_EFFECT_TYPES = {
    "allowlist_or_denylist",
    "tool_permission_or_capability_scope",
    "sandbox_or_dry_run",
    "human_checkpoint_or_arbitration",
    "rollback_or_recovery_gate",
