"""Config-driven notification dispatch for Slack, Discord, and Teams."""

from __future__ import annotations

from dataclasses import dataclass
import json
import os
from pathlib import Path
from typing import Any, Callable, Mapping
from urllib import request
from urllib.error import HTTPError, URLError


JsonMap = dict[str, Any]
Environment = Mapping[str, str]
Sender = Callable[[str, JsonMap, float], JsonMap]

ALLOWED_PROVIDERS = {"discord", "slack", "teams"}
ALLOWED_SEVERITIES = {"debug": 10, "info": 20, "warning": 30, "error": 40, "critical": 50}
DEFAULT_EVENTS = {"approval_needed", "clarification_needed", "long_running_update", "work_completed", "work_failed"}
INLINE_SECRET_FIELDS = {
    "webhook_url",
    "url",
    "token",
    "secret",
    "bearer_token",
    "bot_token",
    "incoming_webhook",
}


@dataclass(frozen=True)
class NotificationEvent:
    """One event that can be sent to configured notification channels."""

    event_type: str
    title: str
    message: str
    severity: str = "info"
    metadata: Mapping[str, str] | None = None


def load_notification_config(path: Path) -> JsonMap:
    """Load a notification config JSON file."""

    with path.open("r", encoding="utf-8") as file:
        data = json.load(file)
    if not isinstance(data, dict):
        raise TypeError("Notification config must be a JSON object.")
    return data


def check_notification_config(
    config: JsonMap,
    *,
    env: Environment | None = None,
    require_secrets: bool = False,
) -> JsonMap:
    """Validate notification settings without sending messages."""

    gaps: list[str] = []
    warnings: list[str] = []
    env = env if env is not None else os.environ

    if not isinstance(config.get("notifications_enabled"), bool):
        gaps.append("notifications_enabled must be a bool.")

    channels = config.get("channels")
    if not isinstance(channels, list) or not channels:
        gaps.append("channels must be a non-empty list.")
    else:
        _check_channels(channels, env, require_secrets, gaps, warnings)

    default_policy = config.get("default_event_policy", {})
    if not isinstance(default_policy, dict):
        gaps.append("default_event_policy must be an object.")
    else:
        dry_run_default = default_policy.get("dry_run_default", True)
        if not isinstance(dry_run_default, bool):
            gaps.append("default_event_policy.dry_run_default must be a bool.")
        minimum_severity = str(default_policy.get("minimum_severity", "info")).lower()
        if minimum_severity not in ALLOWED_SEVERITIES:
            gaps.append("default_event_policy.minimum_severity must be one of debug, info, warning, error, critical.")
        if not _list_of_strings(default_policy.get("enabled_events", list(DEFAULT_EVENTS))):
            gaps.append("default_event_policy.enabled_events must be a list of event names.")

    secret_policy = config.get("secret_policy", {})
    if not isinstance(secret_policy, dict):
        gaps.append("secret_policy must be an object.")
    elif secret_policy.get("store_secrets_in_config") is not False:
        gaps.append("secret_policy.store_secrets_in_config must be false.")

    status = "ready" if not gaps else "rework_required"
    return {
        "status": status,
        "requires_rework": bool(gaps),
        "principle": "Notification config stores only routing policy and environment variable names; webhook URLs stay outside git.",
        "checks": {
            "channels_count": len(channels) if isinstance(channels, list) else 0,
            "enabled_channels_count": len([item for item in channels if isinstance(item, dict) and item.get("enabled")])
            if isinstance(channels, list)
            else 0,
            "require_secrets": require_secrets,
        },
        "gaps": gaps,
        "warnings": warnings,
        "follow_up_actions": [f"Resolve notification config gap: {gap}" for gap in gaps],
    }


def dispatch_notification(
    config: JsonMap,
    event: NotificationEvent,
    *,
    env: Environment | None = None,
    dry_run: bool | None = None,
    timeout: float = 10.0,
    sender: Sender | None = None,
) -> JsonMap:
    """Dispatch one event to enabled channels, or return payload previews in dry-run mode."""

    env = env if env is not None else os.environ
    event_validation = _check_event(event)
    validation = check_notification_config(config, env=env, require_secrets=False)
    if event_validation["requires_rework"] or validation["requires_rework"]:
        return {
            "status": "rework_required",
            "dry_run": True if dry_run is None else dry_run,
            "validation": {"config": validation, "event": event_validation},
            "attempted": [],
            "skipped": [],
            "failed": [],
        }
    event = NotificationEvent(
        event.event_type,
        event.title,
        event.message,
        event.severity.lower(),
        event.metadata,
    )

    default_policy = config.get("default_event_policy", {})
    if dry_run is None:
        dry_run = bool(default_policy.get("dry_run_default", True))

    if not config.get("notifications_enabled", False):
        return {
            "status": "disabled",
            "dry_run": dry_run,
            "validation": validation,
            "attempted": [],
            "skipped": [{"reason": "notifications_disabled"}],
            "failed": [],
        }

    sender = sender or _post_json
    attempted: list[JsonMap] = []
    skipped: list[JsonMap] = []
    failed: list[JsonMap] = []

    for channel in config.get("channels", []):
        decision = _channel_send_decision(channel, event, default_policy, env)
        if not decision["send"]:
            skipped.append(decision["report"])
            continue

        payload = build_provider_payload(str(channel["provider"]).lower(), event, channel)
        webhook_url = env.get(channel["webhook_url_env"], "")
        if dry_run:
            attempted.append(
                {
                    "channel_id": channel["id"],
                    "provider": channel["provider"],
                    "dry_run": True,
                    "webhook_url_env": channel["webhook_url_env"],
                    "payload_preview": payload,
                }
            )
            continue

        try:
            response = sender(webhook_url, payload, timeout)
            attempted.append(
                {
                    "channel_id": channel["id"],
                    "provider": channel["provider"],
                    "dry_run": False,
                    "response": response,
                }
            )
        except NotificationDispatchError as exc:
            failed.append(
                {
                    "channel_id": channel["id"],
                    "provider": channel["provider"],
                    "error": str(exc),
                }
            )

    status = _dispatch_status(attempted, failed, dry_run)
    return {
        "status": status,
        "dry_run": dry_run,
        "validation": validation,
        "attempted": attempted,
        "skipped": skipped,
        "failed": failed,
    }


def build_provider_payload(provider: str, event: NotificationEvent, channel: JsonMap) -> JsonMap:
    """Build the JSON payload expected by a provider webhook."""

    text = _render_text(event, channel)
    provider = provider.lower()
    if provider == "slack":
        return {"text": text}
    if provider == "discord":
        payload: JsonMap = {"content": _limit(text, 2000), "allowed_mentions": {"parse": []}}
        username = _channel_format(channel).get("username", "")
        if isinstance(username, str) and username.strip():
            payload["username"] = username.strip()
        return payload
    if provider == "teams":
        style = str(channel.get("payload_style", "message_card")).lower()
        if style == "simple_text":
            return {"text": text}
        if style == "adaptive_card":
            return {
                "type": "message",
                "attachments": [
                    {
                        "contentType": "application/vnd.microsoft.card.adaptive",
                        "content": {
                            "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
                            "type": "AdaptiveCard",
                            "version": "1.5",
                            "body": [{"type": "TextBlock", "text": text, "wrap": True}],
                        },
                    }
                ],
            }
        return {
            "@type": "MessageCard",
            "@context": "https://schema.org/extensions",
            "summary": _limit(event.title, 200),
            "themeColor": _teams_theme_color(event.severity),
            "text": text,
        }
    raise ValueError(f"Unsupported provider: {provider}")


class NotificationDispatchError(RuntimeError):
    """Raised when a webhook POST fails."""


def _check_channels(
    channels: list[Any],
    env: Environment,
    require_secrets: bool,
    gaps: list[str],
    warnings: list[str],
) -> None:
    seen = set()
    for index, channel in enumerate(channels, start=1):
        label = f"channels[{index}]"
        if not isinstance(channel, dict):
            gaps.append(f"{label} must be an object.")
            continue
        channel_id = str(channel.get("id", "")).strip()
        provider = str(channel.get("provider", "")).strip().lower()
        if not channel_id:
            gaps.append(f"{label}.id is required.")
        elif channel_id in seen:
            gaps.append(f"{label}.id is duplicated: {channel_id}.")
        else:
            seen.add(channel_id)
        if provider not in ALLOWED_PROVIDERS:
            gaps.append(f"{label}.provider must be one of: {', '.join(sorted(ALLOWED_PROVIDERS))}.")
        if not isinstance(channel.get("enabled"), bool):
            gaps.append(f"{label}.enabled must be a bool.")
        webhook_env = channel.get("webhook_url_env")
        if not isinstance(webhook_env, str) or not webhook_env.strip():
            gaps.append(f"{label}.webhook_url_env is required.")
        elif require_secrets and channel.get("enabled") and webhook_env not in env:
            gaps.append(f"{label}.webhook_url_env points to missing environment variable: {webhook_env}.")
        inline_secret_fields = sorted(INLINE_SECRET_FIELDS.intersection(channel))
        if inline_secret_fields:
            gaps.append(f"{label} must not store inline secret fields: {', '.join(inline_secret_fields)}.")
        if "events" in channel and not _list_of_strings(channel["events"]):
            gaps.append(f"{label}.events must be a list of event names.")
        minimum_severity = str(channel.get("minimum_severity", "info")).lower()
        if minimum_severity not in ALLOWED_SEVERITIES:
            gaps.append(f"{label}.minimum_severity must be one of debug, info, warning, error, critical.")
        if provider == "teams" and channel.get("payload_style") not in (None, "simple_text", "message_card", "adaptive_card"):
            gaps.append(f"{label}.payload_style must be simple_text, message_card, or adaptive_card.")
        if provider == "teams":
            warnings.append(f"{label}: Teams connector behavior is changing; prefer Workflows webhook URLs.")


def _check_event(event: NotificationEvent) -> JsonMap:
    gaps = []
    if not event.event_type.strip():
        gaps.append("event_type is required.")
    if not event.title.strip():
        gaps.append("title is required.")
    if not event.message.strip():
        gaps.append("message is required.")
    if event.severity.lower() not in ALLOWED_SEVERITIES:
        gaps.append("severity must be one of debug, info, warning, error, critical.")
    return {"status": "ready" if not gaps else "rework_required", "requires_rework": bool(gaps), "gaps": gaps}


def _channel_send_decision(channel: JsonMap, event: NotificationEvent, default_policy: JsonMap, env: Environment) -> JsonMap:
    channel_id = channel.get("id", "")
    provider = channel.get("provider", "")
    if not channel.get("enabled", False):
        return {"send": False, "report": {"channel_id": channel_id, "provider": provider, "reason": "channel_disabled"}}
    events = channel.get("events") or default_policy.get("enabled_events") or list(DEFAULT_EVENTS)
    if event.event_type not in set(events):
        return {"send": False, "report": {"channel_id": channel_id, "provider": provider, "reason": "event_not_enabled"}}
    minimum_severity = str(channel.get("minimum_severity") or default_policy.get("minimum_severity", "info")).lower()
    if ALLOWED_SEVERITIES[event.severity] < ALLOWED_SEVERITIES[minimum_severity]:
        return {"send": False, "report": {"channel_id": channel_id, "provider": provider, "reason": "below_minimum_severity"}}
    webhook_env = channel.get("webhook_url_env", "")
    if not isinstance(webhook_env, str) or not env.get(webhook_env):
        return {"send": False, "report": {"channel_id": channel_id, "provider": provider, "reason": "missing_webhook_env", "webhook_url_env": webhook_env}}
    return {"send": True, "report": {"channel_id": channel_id, "provider": provider}}


def _post_json(url: str, payload: JsonMap, timeout: float) -> JsonMap:
    data = json.dumps(payload).encode("utf-8")
    webhook_request = request.Request(
        url,
        data=data,
        headers={"Content-Type": "application/json; charset=utf-8", "User-Agent": "agent-platform-notifier/1.0"},
        method="POST",
    )
    try:
        with request.urlopen(webhook_request, timeout=timeout) as response:
            body = response.read().decode("utf-8", errors="replace")
            return {"status_code": response.status, "reason": response.reason, "body": body[:500]}
    except HTTPError as exc:
        body = exc.read().decode("utf-8", errors="replace")
        raise NotificationDispatchError(f"HTTP {exc.code}: {body[:500]}") from exc
    except URLError as exc:
        raise NotificationDispatchError(f"URL error: {exc.reason}") from exc


def _render_text(event: NotificationEvent, channel: JsonMap) -> str:
    metadata = event.metadata or {}
    lines = [
        f"[{event.severity.upper()}] {event.title}",
        event.message,
    ]
    if _channel_format(channel).get("include_event_type", True):
        lines.append(f"event={event.event_type}")
    if metadata:
        meta_text = ", ".join(f"{key}={value}" for key, value in sorted(metadata.items()))
        lines.append(meta_text)
    return "\n".join(line for line in lines if str(line).strip())


def _channel_format(channel: JsonMap) -> JsonMap:
    value = channel.get("format", {})
    return value if isinstance(value, dict) else {}


def _teams_theme_color(severity: str) -> str:
    return {
        "debug": "64748B",
        "info": "2563EB",
        "warning": "D97706",
        "error": "DC2626",
        "critical": "991B1B",
    }.get(severity, "2563EB")


def _dispatch_status(attempted: list[JsonMap], failed: list[JsonMap], dry_run: bool) -> str:
    if failed:
        return "partial_failure" if attempted else "failed"
    if attempted:
        return "dry_run_ready" if dry_run else "sent"
    return "nothing_to_send"


def _limit(value: str, max_length: int) -> str:
    if len(value) <= max_length:
        return value
    return value[: max_length - 3] + "..."


def _list_of_strings(value: Any) -> bool:
    return isinstance(value, list) and all(isinstance(item, str) and item.strip() for item in value)

"""Validate the repository memory bootstrap manifest."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Any


JsonMap = dict[str, Any]

ALLOWED_TIERS = {"hot", "warm", "cold"}
DEFAULT_HOT_LIMIT = 12


@dataclass(frozen=True)
class MemoryAnchor:
    """One durable memory file the agent can load or retrieve."""

    anchor_id: str
    path: str
    tier: str
    purpose: str
    required: bool = True
    load_order: int = 0

    @classmethod
    def from_dict(cls, data: JsonMap) -> "MemoryAnchor":
        return cls(
            anchor_id=_required_string(data, "id"),
            path=_required_string(data, "path"),
            tier=_required_string(data, "tier"),
            purpose=_required_string(data, "purpose"),
            required=_optional_bool(data.get("required", True), "required"),
            load_order=_optional_int(data.get("load_order", 0), "load_order"),
        )


@dataclass(frozen=True)
class MemoryBootstrapManifest:
    """Input manifest that defines what an agent should load at startup."""

    name: str
    schema_version: str
    purpose: str
    anchors: tuple[MemoryAnchor, ...]
    startup_sequence: tuple[str, ...] = ()
    required_anchor_ids: tuple[str, ...] = ()
    hot_context_limit: int = DEFAULT_HOT_LIMIT

    @classmethod
    def from_dict(cls, data: JsonMap) -> "MemoryBootstrapManifest":
        return cls(
            name=_required_string(data, "name"),
            schema_version=_required_string(data, "schema_version"),
            purpose=_required_string(data, "purpose"),
            anchors=tuple(MemoryAnchor.from_dict(item) for item in _list_of_maps(data.get("anchors", []), "anchors")),
            startup_sequence=_tuple_of_strings(data.get("startup_sequence", []), "startup_sequence"),
            required_anchor_ids=_tuple_of_strings(data.get("required_anchor_ids", []), "required_anchor_ids"),
            hot_context_limit=_optional_int(data.get("hot_context_limit", DEFAULT_HOT_LIMIT), "hot_context_limit"),
        )


def check_memory_bootstrap(manifest: MemoryBootstrapManifest, repo_root: Path) -> JsonMap:
    """Return whether memory bootstrap files are ready for a new agent session."""

    gaps = []
    warnings = []
    repo_root = repo_root.resolve()

    if not manifest.name.strip():
        gaps.append("Manifest name is missing.")
    if not manifest.schema_version.strip():
        gaps.append("Manifest schema_version is missing.")
    if not manifest.purpose.strip():
        gaps.append("Manifest purpose is missing.")
    if not manifest.anchors:
        gaps.append("Memory anchors are missing.")

    anchors_by_id = {anchor.anchor_id: anchor for anchor in manifest.anchors}
    if len(anchors_by_id) != len(manifest.anchors):
        gaps.append("Memory anchor IDs must be unique.")

    for anchor in manifest.anchors:
        gaps.extend(_validate_anchor(anchor, repo_root))

    for required_anchor_id in manifest.required_anchor_ids:
        if required_anchor_id not in anchors_by_id:
            gaps.append(f"Required anchor is missing from anchors: {required_anchor_id}.")

    for sequence_id in manifest.startup_sequence:
        if sequence_id not in anchors_by_id:
            gaps.append(f"Startup sequence references unknown anchor: {sequence_id}.")

    hot_anchors = [anchor for anchor in manifest.anchors if anchor.tier == "hot"]
    if not hot_anchors:
        gaps.append("At least one hot memory anchor is required.")
    if len(hot_anchors) > manifest.hot_context_limit:
        warnings.append(f"Hot memory anchor count exceeds limit {manifest.hot_context_limit}; move lower-priority anchors to warm or cold.")

    startup_order = _startup_order(manifest, anchors_by_id)
    status = "memory_bootstrap_required" if gaps else "ready_to_bootstrap"

    return {
        "status": status,
        "requires_rework": bool(gaps),
        "principle": "Do not rely on chat memory; load durable repository memory anchors before work.",
        "checks": {
            "anchors_count": len(manifest.anchors),
            "hot_count": len(hot_anchors),
            "warm_count": sum(1 for anchor in manifest.anchors if anchor.tier == "warm"),
            "cold_count": sum(1 for anchor in manifest.anchors if anchor.tier == "cold"),
            "required_anchor_count": len(manifest.required_anchor_ids),
            "startup_sequence_count": len(manifest.startup_sequence),
        },
        "startup_order": [
            {
                "id": anchor.anchor_id,
                "path": anchor.path,
                "tier": anchor.tier,
                "purpose": anchor.purpose,
            }
            for anchor in startup_order
        ],
        "hot_context_paths": [anchor.path for anchor in startup_order if anchor.tier == "hot"],
        "gaps": gaps,
        "warnings": warnings,
        "follow_up_actions": [f"Resolve memory bootstrap gap: {gap}" for gap in gaps],
    }


def _validate_anchor(anchor: MemoryAnchor, repo_root: Path) -> list[str]:
    gaps = []

    if not anchor.anchor_id.strip():
        gaps.append("Memory anchor has an empty id.")
    if not anchor.path.strip():
        gaps.append(f"Memory anchor {anchor.anchor_id} has an empty path.")
    if anchor.tier not in ALLOWED_TIERS:
        gaps.append(f"Memory anchor {anchor.anchor_id} has unknown tier: {anchor.tier}.")
    if not anchor.purpose.strip():
        gaps.append(f"Memory anchor {anchor.anchor_id} purpose is missing.")
    if anchor.required and not (repo_root / anchor.path).exists():
        gaps.append(f"Required memory anchor path does not exist: {anchor.path}.")
    return gaps


def _startup_order(manifest: MemoryBootstrapManifest, anchors_by_id: dict[str, MemoryAnchor]) -> tuple[MemoryAnchor, ...]:
    ordered = [anchors_by_id[anchor_id] for anchor_id in manifest.startup_sequence if anchor_id in anchors_by_id]
    ordered_ids = {anchor.anchor_id for anchor in ordered}
    remaining = sorted(
        (anchor for anchor in manifest.anchors if anchor.anchor_id not in ordered_ids),
        key=lambda anchor: (anchor.tier != "hot", anchor.load_order, anchor.anchor_id),
    )
    return tuple(ordered + remaining)


def _required_string(data: JsonMap, field_name: str) -> str:
    value = data.get(field_name)
    if not isinstance(value, str):
        raise TypeError(f"{field_name} must be a string.")
    return value


def _optional_bool(value: Any, field_name: str) -> bool:
    if not isinstance(value, bool):
        raise TypeError(f"{field_name} must be a bool.")
    return value


def _optional_int(value: Any, field_name: str) -> int:
    if not isinstance(value, int):
        raise TypeError(f"{field_name} must be an integer.")
    return value


def _tuple_of_strings(value: Any, field_name: str) -> tuple[str, ...]:
    if not isinstance(value, list | tuple):
        raise TypeError(f"{field_name} must be a list of strings.")
    if not all(isinstance(item, str) for item in value):
        raise TypeError(f"{field_name} must contain only strings.")
    return tuple(value)


def _list_of_maps(value: Any, field_name: str) -> list[JsonMap]:
    if not isinstance(value, list):
        raise TypeError(f"{field_name} must be a list of objects.")
    if not all(isinstance(item, dict) for item in value):
        raise TypeError(f"{field_name} must contain only objects.")
    return value

"""Validate agent creation and orchestration registry contracts."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any


JsonMap = dict[str, Any]

REQUIRED_TOP_LEVEL_FIELDS = {
    "schema_version",
    "name",
    "purpose",
    "reader_guide",
    "reference_links",
    "structure_rules",
    "field_guide",
    "platform_principle",
    "agent_spec_contract",
    "agent_blueprints",
    "creation_pipeline",
    "orchestration_patterns",
    "orchestration_controls",
    "lifecycle_gates",
    "validation_commands",
}

REQUIRED_AGENT_SPEC_FIELDS = {"name", "description", "runtime", "skills", "tools", "metadata"}
REQUIRED_BLUEPRINT_FIELDS = {"blueprint_id", "purpose", "default_runtime", "spec_template_path", "creation_gates", "validation_commands"}
REQUIRED_PATTERN_FIELDS = {
    "pattern_id",
    "use_when",
    "coordination_model",
    "state_contract",
    "handoff_contract",
    "observability_contract",
    "failure_policy",
    "required_gates",
}
REQUIRED_PATTERN_IDS = {"single_agent", "supervisor_router", "sequential_pipeline", "parallel_fanout_merge", "handoff_network"}
REQUIRED_CONTROL_IDS = {"state", "handoff", "tool_access", "human_checkpoint", "observability", "resource", "evaluation"}
REQUIRED_GATE_IDS = {"intake", "research", "spec", "creation", "orchestration", "validation", "evaluation"}


def load_agent_orchestration_registry(path: Path) -> JsonMap:
    """Load an agent orchestration registry JSON file."""

    with path.open("r", encoding="utf-8") as file:
        data = json.load(file)
    if not isinstance(data, dict):
        raise ValueError("Agent orchestration registry must be a JSON object.")
    return data


def check_agent_orchestration_registry(registry: JsonMap) -> JsonMap:
    """Return deterministic readiness for the agent creation/orchestration registry."""

    gaps: list[str] = []
    warnings: list[str] = []

    missing_top_level = sorted(REQUIRED_TOP_LEVEL_FIELDS - set(registry))
    if missing_top_level:
        gaps.append(f"Missing top-level fields: {', '.join(missing_top_level)}.")

    _check_reader_contract(registry, gaps)
    _check_agent_spec_contract(registry.get("agent_spec_contract", {}), gaps, warnings)
    _check_blueprints(registry.get("agent_blueprints", []), gaps, warnings)
    _check_creation_pipeline(registry.get("creation_pipeline", []), gaps)
    _check_patterns(registry.get("orchestration_patterns", []), gaps, warnings)
    _check_controls(registry.get("orchestration_controls", []), gaps)
    _check_lifecycle_gates(registry.get("lifecycle_gates", []), gaps)
    _check_validation_commands(registry.get("validation_commands", []), gaps)

    requires_rework = bool(gaps)
    return {
        "status": "rework_required" if requires_rework else "ready",
        "requires_rework": requires_rework,
        "checks": {
            "blueprint_count": len(registry.get("agent_blueprints", [])) if isinstance(registry.get("agent_blueprints"), list) else 0,
            "creation_pipeline_steps": len(registry.get("creation_pipeline", [])) if isinstance(registry.get("creation_pipeline"), list) else 0,
            "orchestration_pattern_count": len(registry.get("orchestration_patterns", []))
            if isinstance(registry.get("orchestration_patterns"), list)
            else 0,
            "control_count": len(registry.get("orchestration_controls", []))
            if isinstance(registry.get("orchestration_controls"), list)
            else 0,
            "lifecycle_gate_count": len(registry.get("lifecycle_gates", [])) if isinstance(registry.get("lifecycle_gates"), list) else 0,
            "validation_command_count": len(registry.get("validation_commands", []))
            if isinstance(registry.get("validation_commands"), list)
            else 0,
        },
        "gaps": gaps,
        "warnings": warnings,
        "follow_up_actions": [f"Resolve agent orchestration gap: {gap}" for gap in gaps],
    }


def _check_reader_contract(registry: JsonMap, gaps: list[str]) -> None:
    if not _non_empty_string(registry.get("schema_version")):
        gaps.append("schema_version is missing.")
    if not _non_empty_string(registry.get("name")):
        gaps.append("name is missing.")
    if not _non_empty_string(registry.get("purpose")):
        gaps.append("purpose is missing.")
    if not isinstance(registry.get("reader_guide"), dict):
        gaps.append("reader_guide must be an object.")
    if not _non_empty_list(registry.get("reference_links")):
        gaps.append("reference_links must be a non-empty list.")
    if not _non_empty_list(registry.get("structure_rules")):
        gaps.append("structure_rules must be a non-empty list.")
    if not _non_empty_list(registry.get("field_guide")):
        gaps.append("field_guide must be a non-empty list.")
    if not _non_empty_string(registry.get("platform_principle")):
        gaps.append("platform_principle is missing.")


def _check_agent_spec_contract(contract: Any, gaps: list[str], warnings: list[str]) -> None:
    if not isinstance(contract, dict):
        gaps.append("agent_spec_contract must be an object.")
        return
    required_fields = set(_string_list(contract.get("required_fields")))
    missing = sorted(REQUIRED_AGENT_SPEC_FIELDS - required_fields)
    if missing:
        gaps.append(f"agent_spec_contract.required_fields is missing: {', '.join(missing)}.")
    metadata = contract.get("required_metadata")
    if not isinstance(metadata, list) or not metadata:
        gaps.append("agent_spec_contract.required_metadata must be a non-empty list.")
    if "input_contract" not in contract or "output_contract" not in contract:
        warnings.append("agent_spec_contract should document input_contract and output_contract for generated agents.")


def _check_blueprints(blueprints: Any, gaps: list[str], warnings: list[str]) -> None:
    if not isinstance(blueprints, list) or not blueprints:
        gaps.append("agent_blueprints must be a non-empty list.")
        return

    blueprint_ids: list[str] = []
    for blueprint in blueprints:
        if not isinstance(blueprint, dict):
            gaps.append("agent_blueprints entries must be objects.")
            continue
        blueprint_id = str(blueprint.get("blueprint_id", ""))
        label = blueprint_id or "<unnamed-blueprint>"
        blueprint_ids.append(blueprint_id)
        missing = sorted(field for field in REQUIRED_BLUEPRINT_FIELDS if not blueprint.get(field))
        if missing:
            gaps.append(f"Blueprint {label} is missing fields: {', '.join(missing)}.")
        if not _non_empty_list(blueprint.get("creation_gates")):
            gaps.append(f"Blueprint {label} needs creation_gates.")
        if not _non_empty_list(blueprint.get("validation_commands")):
            gaps.append(f"Blueprint {label} needs validation_commands.")
        if not _non_empty_list(blueprint.get("docs_targets")):
            warnings.append(f"Blueprint {label} has no docs_targets.")

    duplicated = sorted({blueprint_id for blueprint_id in blueprint_ids if blueprint_ids.count(blueprint_id) > 1 and blueprint_id})
    for blueprint_id in duplicated:
        gaps.append(f"Duplicate blueprint_id '{blueprint_id}'.")


def _check_creation_pipeline(pipeline: Any, gaps: list[str]) -> None:
    if not isinstance(pipeline, list) or len(pipeline) < 5:
        gaps.append("creation_pipeline must have at least five ordered steps.")
        return
    step_ids = [step.get("step_id") for step in pipeline if isinstance(step, dict)]
    for required in ("intake", "blueprint_select", "spec_write", "validation", "registry_update"):
        if required not in step_ids:
            gaps.append(f"creation_pipeline is missing step_id '{required}'.")


def _check_patterns(patterns: Any, gaps: list[str], warnings: list[str]) -> None:
    if not isinstance(patterns, list) or not patterns:
        gaps.append("orchestration_patterns must be a non-empty list.")
        return

    pattern_ids: list[str] = []
    for pattern in patterns:
        if not isinstance(pattern, dict):
            gaps.append("orchestration_patterns entries must be objects.")
            continue
        pattern_id = str(pattern.get("pattern_id", ""))
        label = pattern_id or "<unnamed-pattern>"
        pattern_ids.append(pattern_id)
        missing = sorted(field for field in REQUIRED_PATTERN_FIELDS if not pattern.get(field))
        if missing:
            gaps.append(f"Pattern {label} is missing fields: {', '.join(missing)}.")
        for contract_field in ("state_contract", "handoff_contract", "observability_contract", "failure_policy"):
            if contract_field in pattern and not isinstance(pattern[contract_field], dict):
                gaps.append(f"Pattern {label}.{contract_field} must be an object.")
        if not _non_empty_list(pattern.get("required_gates")):
            warnings.append(f"Pattern {label} has no required_gates.")

    missing_patterns = sorted(REQUIRED_PATTERN_IDS - set(pattern_ids))
    if missing_patterns:
        gaps.append(f"orchestration_patterns is missing required patterns: {', '.join(missing_patterns)}.")
    duplicated = sorted({pattern_id for pattern_id in pattern_ids if pattern_ids.count(pattern_id) > 1 and pattern_id})
    for pattern_id in duplicated:
        gaps.append(f"Duplicate pattern_id '{pattern_id}'.")


def _check_controls(controls: Any, gaps: list[str]) -> None:
    if not isinstance(controls, list) or not controls:
        gaps.append("orchestration_controls must be a non-empty list.")
        return
    control_ids = {control.get("control_id") for control in controls if isinstance(control, dict)}
    missing = sorted(REQUIRED_CONTROL_IDS - control_ids)
    if missing:
        gaps.append(f"orchestration_controls is missing required controls: {', '.join(missing)}.")
    for control in controls:
        if not isinstance(control, dict):
            gaps.append("orchestration_controls entries must be objects.")
            continue
        label = control.get("control_id") or "<unnamed-control>"
        if not _non_empty_string(control.get("rule")):
            gaps.append(f"Control {label} is missing rule.")
        if not _non_empty_list(control.get("verification")):
            gaps.append(f"Control {label} is missing verification.")


def _check_lifecycle_gates(gates: Any, gaps: list[str]) -> None:
    if not isinstance(gates, list) or not gates:
        gaps.append("lifecycle_gates must be a non-empty list.")
        return
    gate_ids = {gate.get("gate_id") for gate in gates if isinstance(gate, dict)}
    missing = sorted(REQUIRED_GATE_IDS - gate_ids)
    if missing:
        gaps.append(f"lifecycle_gates is missing required gates: {', '.join(missing)}.")


def _check_validation_commands(commands: Any, gaps: list[str]) -> None:
    if not _non_empty_list(commands):
        gaps.append("validation_commands must be a non-empty list.")
        return
    command_text = "\n".join(str(command) for command in commands)
    for required in ("check-agent-orchestration", "list-agents", "inspect-agent"):
        if required not in command_text:
            gaps.append(f"validation_commands must include {required}.")


def _string_list(value: Any) -> list[str]:
    if not isinstance(value, list | tuple):
        return []
    return [item for item in value if isinstance(item, str)]


def _non_empty_list(value: Any) -> bool:
    return isinstance(value, list) and bool(value)


def _non_empty_string(value: Any) -> bool:
    return isinstance(value, str) and bool(value.strip())

"""Plan manager-as-tools orchestration from registered agent specs."""

from __future__ import annotations

import re
from dataclasses import dataclass
from typing import Any

from agent_platform.core.models import AgentSpec
from agent_platform.core.registry import AgentRegistry


JsonMap = dict[str, Any]

DEFAULT_MANAGER_AGENT = "agent-orchestrator-agent"
DEFAULT_PATTERN = "supervisor_router"
STOPWORDS = {
    "a",
    "an",
    "and",
    "as",
    "by",
    "for",
    "from",
    "in",
    "into",
    "of",
    "on",
    "or",
    "the",
    "to",
    "with",
}


@dataclass(frozen=True)
class ManagerToolPlanInput:
    """Input for creating a manager agent plus subagent tool plan."""

    goal: str
    context: str = ""
    manager_agent: str = DEFAULT_MANAGER_AGENT
    preferred_pattern: str = DEFAULT_PATTERN
    requested_agents: tuple[str, ...] = ()
    required_capabilities: tuple[str, ...] = ()
    allowed_tools: tuple[str, ...] = ()
    blocked_tools: tuple[str, ...] = ()
    human_checkpoint_triggers: tuple[str, ...] = ()
    output_targets: tuple[str, ...] = ()
    validation_targets: tuple[str, ...] = ()
    constraints: tuple[str, ...] = ()
    max_subagents: int = 5

    @classmethod
    def from_dict(cls, data: JsonMap) -> "ManagerToolPlanInput":
        return cls(
            goal=_required_string(data, "goal"),
            context=_optional_string(data.get("context", ""), "context"),
            manager_agent=_optional_string(data.get("manager_agent", DEFAULT_MANAGER_AGENT), "manager_agent")
            or DEFAULT_MANAGER_AGENT,
            preferred_pattern=_optional_string(data.get("preferred_pattern", DEFAULT_PATTERN), "preferred_pattern")
            or DEFAULT_PATTERN,
            requested_agents=_tuple_of_strings(data.get("requested_agents", ()), "requested_agents"),
            required_capabilities=_tuple_of_strings(data.get("required_capabilities", ()), "required_capabilities"),
            allowed_tools=_tuple_of_strings(data.get("allowed_tools", ()), "allowed_tools"),
            blocked_tools=_tuple_of_strings(data.get("blocked_tools", ()), "blocked_tools"),
            human_checkpoint_triggers=_tuple_of_strings(
                data.get("human_checkpoint_triggers", ()), "human_checkpoint_triggers"
            ),
            output_targets=_tuple_of_strings(data.get("output_targets", ()), "output_targets"),
            validation_targets=_tuple_of_strings(data.get("validation_targets", ()), "validation_targets"),
            constraints=_tuple_of_strings(data.get("constraints", ()), "constraints"),
            max_subagents=_optional_int(data.get("max_subagents", 5), "max_subagents"),
        )


def plan_manager_tool_orchestration(
    plan_input: ManagerToolPlanInput,
    agent_registry: AgentRegistry,
    orchestration_registry: JsonMap,
) -> JsonMap:
    """Build a deterministic manager-as-tools plan from local registry data."""

    gaps: list[str] = []
    warnings: list[str] = []

    if not plan_input.goal.strip():
        gaps.append("goal is required.")
    if plan_input.max_subagents < 1:
        gaps.append("max_subagents must be at least 1.")

    agents_by_name = {agent.name: agent for agent in agent_registry.list_agents()}
    manager = agents_by_name.get(plan_input.manager_agent)
    if manager is None:
        gaps.append(f"manager_agent '{plan_input.manager_agent}' is not registered.")

    patterns_by_id = _patterns_by_id(orchestration_registry)
    selected_pattern = patterns_by_id.get(plan_input.preferred_pattern)
    if selected_pattern is None:
        gaps.append(f"preferred_pattern '{plan_input.preferred_pattern}' is not in the orchestration registry.")
        selected_pattern = patterns_by_id.get(DEFAULT_PATTERN, {})

    selected_agents, scoring_notes = _select_subagents(plan_input, agents_by_name, warnings, gaps)
    if not selected_agents:
        gaps.append("No subagents were selected; request agents explicitly or add required_capabilities that match registered specs.")

    subagent_tools = [
        _subagent_tool(agent, plan_input, scoring_notes.get(agent.name, ("explicitly requested",))) for agent in selected_agents
    ]
    controls = _controls(orchestration_registry)
    default_validation_commands = [
        "PYTHONPATH=src python3 -m agent_platform.cli check-agent-orchestration configs/orchestration/agent-orchestration-registry.json",
        "PYTHONPATH=src python3 -m agent_platform.cli list-agents --registry configs/agents",
        f"PYTHONPATH=src python3 -m agent_platform.cli inspect-agent configs/agents/{plan_input.manager_agent}.json",
    ]
    validation_commands = tuple(dict.fromkeys((*default_validation_commands, *plan_input.validation_targets)))

    status = "rework_required" if gaps else "ready_to_orchestrate"
    return {
        "status": status,
        "requires_rework": bool(gaps),
        "orchestration_model": "manager_as_tools",
        "manager_agent": _agent_ref(manager) if manager is not None else {"name": plan_input.manager_agent, "registered": False},
        "selected_pattern": {
            "pattern_id": plan_input.preferred_pattern,
            "coordination_model": selected_pattern.get("coordination_model", ""),
            "state_contract": selected_pattern.get("state_contract", {}),
            "handoff_contract": selected_pattern.get("handoff_contract", {}),
            "failure_policy": selected_pattern.get("failure_policy", {}),
        },
        "subagent_tools": subagent_tools,
        "execution_plan": _execution_plan(plan_input, subagent_tools),
        "controls": controls,
        "human_checkpoints": _human_checkpoints(plan_input, controls),
        "observability": {
            "minimum_records": selected_pattern.get("observability_contract", {}).get(
                "minimum_records",
                ["route decision", "subagent tool calls", "merge decision", "validation result"],
            ),
            "trace_fields": [
                "goal",
                "manager_agent",
                "selected_pattern",
                "subagent_tools",
                "routing_reason",
                "tool_outputs",
                "merge_decision",
                "validation_commands",
            ],
        },
        "validation_commands": list(validation_commands),
        "output_targets": list(plan_input.output_targets),
        "constraints": list(plan_input.constraints),
        "gaps": gaps,
        "warnings": warnings,
        "follow_up_actions": [f"Resolve manager tool orchestration gap: {gap}" for gap in gaps],
    }


def _select_subagents(
    plan_input: ManagerToolPlanInput,
    agents_by_name: dict[str, AgentSpec],
    warnings: list[str],
    gaps: list[str],
) -> tuple[list[AgentSpec], dict[str, tuple[str, ...]]]:
    if plan_input.requested_agents:
        selected = []
        notes: dict[str, tuple[str, ...]] = {}
        for name in plan_input.requested_agents:
            if name == plan_input.manager_agent:
                gaps.append("manager_agent cannot also be listed in requested_agents.")
                continue
            agent = agents_by_name.get(name)
            if agent is None:
                gaps.append(f"requested agent '{name}' is not registered.")
                continue
            selected.append(agent)
            notes[name] = ("explicitly requested",)
        return selected[: plan_input.max_subagents], notes

    query = " ".join(
        (
            plan_input.goal,
            plan_input.context,
            " ".join(plan_input.required_capabilities),
            " ".join(plan_input.output_targets),
        )
    )
    scored: list[tuple[int, str, AgentSpec, tuple[str, ...]]] = []
    for agent in agents_by_name.values():
        if agent.name == plan_input.manager_agent:
            continue
        score, reasons = _score_agent(query, plan_input.required_capabilities, agent)
        if score > 0:
            scored.append((score, agent.name, agent, reasons))

    scored.sort(key=lambda item: (-item[0], item[1]))
    selected = [agent for _, _, agent, _ in scored[: plan_input.max_subagents]]
    notes = {agent.name: reasons for _, _, agent, reasons in scored[: plan_input.max_subagents]}
    if not selected and agents_by_name:
        warnings.append("No registered subagent matched the goal or required capabilities.")
    return selected, notes


def _score_agent(query: str, required_capabilities: tuple[str, ...], agent: AgentSpec) -> tuple[int, tuple[str, ...]]:
    haystack = _agent_haystack(agent)
    query_tokens = _tokens(query)
    agent_tokens = _tokens(haystack)
    overlaps = sorted(query_tokens.intersection(agent_tokens))
    score = len(overlaps)
    reasons = [f"keyword:{token}" for token in overlaps[:8]]

    normalized_haystack = haystack.lower()
    for capability in required_capabilities:
        capability_tokens = _tokens(capability)
        if capability.lower() in normalized_haystack:
            score += 4
            reasons.append(f"capability:{capability}")
        else:
            matched = sorted(capability_tokens.intersection(agent_tokens))
            if matched:
                score += len(matched)
                reasons.append(f"capability_tokens:{'/'.join(matched[:4])}")

    return score, tuple(reasons or ("metadata match",))


def _subagent_tool(agent: AgentSpec, plan_input: ManagerToolPlanInput, match_reasons: tuple[str, ...]) -> JsonMap:
    allowed_tool_set = set(plan_input.allowed_tools)
    blocked_tool_set = set(plan_input.blocked_tools)
    agent_tools = [tool for tool in agent.tools if tool not in blocked_tool_set]
    if allowed_tool_set:
        agent_tools = [tool for tool in agent_tools if tool in allowed_tool_set]

    return {
        "tool_name": f"run_{_slug(agent.name)}",
        "agent_name": agent.name,
        "tool_description": agent.description,
        "match_reasons": list(match_reasons),
        "input_contract": agent.metadata.get(
            "input_schema",
            "structured task payload with task_id, scope, inputs, expected_outputs, constraints, and blocked_decisions",
        ),
        "output_contract": agent.metadata.get(
            "output_contract",
            "structured agent result with summary, artifacts, evidence, risks, validation, and next_action",
        ),
        "allowed_tools": agent_tools,
        "blocked_tools": [tool for tool in agent.tools if tool in blocked_tool_set],
        "policy": agent.metadata.get("policy", ""),
        "docs_targets": agent.metadata.get("docs_targets", []),
    }


def _execution_plan(plan_input: ManagerToolPlanInput, subagent_tools: list[JsonMap]) -> list[JsonMap]:
    invocation_mode = "parallel" if plan_input.preferred_pattern == "parallel_fanout_merge" else "bounded_sequence"
    return [
        {
            "stage_id": "route",
            "owner": plan_input.manager_agent,
            "action": "Classify the goal, confirm constraints, and choose which subagent tools to call.",
            "required_output": "routing_reason and selected subagent tool list",
        },
        {
            "stage_id": "invoke_subagent_tools",
            "owner": plan_input.manager_agent,
            "action": f"Call selected subagent tools using {invocation_mode}.",
            "tools": [tool["tool_name"] for tool in subagent_tools],
            "required_output": "tool_outputs with provenance, risks, and validation notes",
        },
        {
            "stage_id": "merge",
            "owner": plan_input.manager_agent,
            "action": "Merge subagent outputs, resolve contradictions, and keep the manager in control of the final answer.",
            "required_output": "merged_result and unresolved_risks",
        },
        {
            "stage_id": "evaluate",
            "owner": plan_input.manager_agent,
            "action": "Run required validation commands and record close-out evidence.",
            "required_output": "validation_result, omissions, and next_action",
        },
    ]


def _human_checkpoints(plan_input: ManagerToolPlanInput, controls: list[JsonMap]) -> JsonMap:
    default_triggers = [
        "destructive file operations",
        "secret-bearing input",
        "new dependency installation",
        "public release",
        "cost-impacting external run",
        "irreversible trade-off",
    ]
    return {
        "triggers": list(dict.fromkeys((*default_triggers, *plan_input.human_checkpoint_triggers))),
        "control": next((control for control in controls if control.get("control_id") == "human_checkpoint"), {}),
    }


def _agent_ref(agent: AgentSpec) -> JsonMap:
    return {
        "name": agent.name,
        "runtime": agent.runtime,
        "description": agent.description,
        "tools": list(agent.tools),
        "status": agent.metadata.get("status", "unknown"),
    }


def _patterns_by_id(orchestration_registry: JsonMap) -> dict[str, JsonMap]:
    patterns = orchestration_registry.get("orchestration_patterns", [])
    if not isinstance(patterns, list):
        return {}
    return {str(pattern.get("pattern_id")): pattern for pattern in patterns if isinstance(pattern, dict)}


def _controls(orchestration_registry: JsonMap) -> list[JsonMap]:
    controls = orchestration_registry.get("orchestration_controls", [])
    if not isinstance(controls, list):
        return []
    return [control for control in controls if isinstance(control, dict)]


def _agent_haystack(agent: AgentSpec) -> str:
    metadata_values = " ".join(str(value) for value in agent.metadata.values() if isinstance(value, str))
    return " ".join((agent.name, agent.description, " ".join(agent.skills), " ".join(agent.tools), metadata_values))


def _tokens(text: str) -> set[str]:
    return {token for token in re.findall(r"[a-z0-9_]+", text.lower()) if len(token) > 2 and token not in STOPWORDS}


def _slug(value: str) -> str:
    slug = re.sub(r"[^a-z0-9]+", "_", value.lower()).strip("_")
    return slug or "agent"


def _tuple_of_strings(value: Any, field_name: str) -> tuple[str, ...]:
    if value is None:
        return ()
    if not isinstance(value, list | tuple):
        raise TypeError(f"{field_name} must be a list of strings.")
    if not all(isinstance(item, str) for item in value):
        raise TypeError(f"{field_name} must contain only strings.")
    return tuple(value)


def _required_string(data: JsonMap, field_name: str) -> str:
    value = data.get(field_name)
    if not isinstance(value, str):
        raise TypeError(f"{field_name} must be a string.")
    return value


def _optional_string(value: Any, field_name: str) -> str:
    if value is None:
        return ""
    if not isinstance(value, str):
        raise TypeError(f"{field_name} must be a string.")
    return value


def _optional_int(value: Any, field_name: str) -> int:
    if not isinstance(value, int):
        raise TypeError(f"{field_name} must be an integer.")
    return value

"""Plan safe parallel work from task dependencies and file/resource boundaries."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any


JsonMap = dict[str, Any]

ALLOWED_WORK_MODES = {"quick", "standard", "ship_first", "research", "governance"}
ALLOWED_RISK_LEVELS = {"low", "medium", "high"}


@dataclass(frozen=True)
class ParallelWorkTask:
    """One candidate unit of parallel work."""

    task_id: str
    title: str
    owner: str
    scope: str
    dependencies: tuple[str, ...] = ()
    touch_paths: tuple[str, ...] = ()
    output_targets: tuple[str, ...] = ()
    verification_steps: tuple[str, ...] = ()
    risk_level: str = "medium"
    parallelizable: bool = True
    notes: str = ""

    @classmethod
    def from_dict(cls, data: JsonMap) -> "ParallelWorkTask":
        return cls(
            task_id=_required_string(data, "task_id"),
            title=_required_string(data, "title"),
            owner=_required_string(data, "owner"),
            scope=_required_string(data, "scope"),
            dependencies=_tuple_of_strings(data.get("dependencies", []), "dependencies"),
            touch_paths=_tuple_of_strings(data.get("touch_paths", []), "touch_paths"),
            output_targets=_tuple_of_strings(data.get("output_targets", []), "output_targets"),
            verification_steps=_tuple_of_strings(data.get("verification_steps", []), "verification_steps"),
            risk_level=_optional_string(data.get("risk_level", "medium"), "risk_level"),
            parallelizable=_optional_bool(data.get("parallelizable", True), "parallelizable"),
            notes=_optional_string(data.get("notes", ""), "notes"),
        )


@dataclass(frozen=True)
class ParallelMergeGate:
    """A fan-in point that waits for parallel lanes and merges their outputs."""

    gate_id: str
    title: str
    wait_for: tuple[str, ...]
    merge_task_id: str
    merge_outputs: tuple[str, ...] = ()
    acceptance_checks: tuple[str, ...] = ()
    notes: str = ""

    @classmethod
    def from_dict(cls, data: JsonMap) -> "ParallelMergeGate":
        return cls(
            gate_id=_required_string(data, "gate_id"),
            title=_required_string(data, "title"),
            wait_for=_tuple_of_strings(data.get("wait_for", []), "wait_for"),
            merge_task_id=_required_string(data, "merge_task_id"),
            merge_outputs=_tuple_of_strings(data.get("merge_outputs", []), "merge_outputs"),
            acceptance_checks=_tuple_of_strings(data.get("acceptance_checks", []), "acceptance_checks"),
            notes=_optional_string(data.get("notes", ""), "notes"),
        )


@dataclass(frozen=True)
class ParallelWorkPlanInput:
    """Structured input for deciding whether work can be split safely."""

    objective: str
    work_mode: str = "standard"
    tasks: tuple[ParallelWorkTask, ...] = ()
    merge_gates: tuple[ParallelMergeGate, ...] = ()
    shared_resources: tuple[str, ...] = ()
    conflict_controls: tuple[str, ...] = ()
    coordination_targets: tuple[str, ...] = ()
    merge_strategy: str = ""
    communication_checkpoints: tuple[str, ...] = ()
    verification_steps: tuple[str, ...] = ()
    rollback_plan: tuple[str, ...] = ()
    source_value_provenance: tuple[str, ...] = ()
    plan_evidence: tuple[str, ...] = ()
    plan_history_targets: tuple[str, ...] = ()

    @classmethod
    def from_dict(cls, data: JsonMap) -> "ParallelWorkPlanInput":
        return cls(
            objective=_required_string(data, "objective"),
            work_mode=_optional_string(data.get("work_mode", "standard"), "work_mode"),
            tasks=tuple(ParallelWorkTask.from_dict(item) for item in _list_of_maps(data.get("tasks", []), "tasks")),
            merge_gates=tuple(
                ParallelMergeGate.from_dict(item) for item in _list_of_maps(data.get("merge_gates", []), "merge_gates")
            ),
            shared_resources=_tuple_of_strings(data.get("shared_resources", []), "shared_resources"),
            conflict_controls=_tuple_of_strings(data.get("conflict_controls", []), "conflict_controls"),
            coordination_targets=_tuple_of_strings(data.get("coordination_targets", []), "coordination_targets"),
            merge_strategy=_optional_string(data.get("merge_strategy", ""), "merge_strategy"),
            communication_checkpoints=_tuple_of_strings(data.get("communication_checkpoints", []), "communication_checkpoints"),
            verification_steps=_tuple_of_strings(data.get("verification_steps", []), "verification_steps"),
            rollback_plan=_tuple_of_strings(data.get("rollback_plan", []), "rollback_plan"),
            source_value_provenance=_tuple_of_strings(data.get("source_value_provenance", []), "source_value_provenance"),
            plan_evidence=_tuple_of_strings(data.get("plan_evidence", []), "plan_evidence"),
            plan_history_targets=_tuple_of_strings(data.get("plan_history_targets", []), "plan_history_targets"),
        )


def plan_parallel_work(plan_input: ParallelWorkPlanInput) -> JsonMap:
    """Return whether a task graph is safe and useful for parallel execution."""

    gaps = []
    warnings = []
    work_mode = plan_input.work_mode.strip().lower() or "standard"
    task_ids = [task.task_id.strip() for task in plan_input.tasks]
    task_by_id = {task.task_id.strip(): task for task in plan_input.tasks if task.task_id.strip()}

    if not plan_input.objective.strip():
        gaps.append("Objective is missing.")
    if work_mode not in ALLOWED_WORK_MODES:
        gaps.append(f"Unknown work_mode '{plan_input.work_mode}'. Use one of: {', '.join(sorted(ALLOWED_WORK_MODES))}.")
    if len(plan_input.tasks) < 2:
        gaps.append("At least two tasks are required before parallel planning is useful.")

    _validate_task_fields(plan_input.tasks, gaps)
    if len(set(task_ids)) != len(task_ids):
        gaps.append("Task IDs must be unique.")
    _validate_dependencies(plan_input.tasks, task_by_id, gaps)
    _validate_merge_gates(plan_input.merge_gates, task_by_id, gaps)

    cycle_path = _find_cycle(plan_input.tasks)
    if cycle_path:
        gaps.append(f"Task dependency graph contains a cycle: {' -> '.join(cycle_path)}.")

    if not plan_input.conflict_controls:
        gaps.append("Conflict controls are missing; record file ownership, lock, branch, or handoff rules for parallel work.")
    if not plan_input.coordination_targets:
        gaps.append("Coordination targets are missing; record where active lanes and status will be tracked.")
    elif not any(target.strip().replace("\\", "/") == "_ops/coordination/status.json" for target in plan_input.coordination_targets):
        warnings.append("Coordination targets do not include _ops/coordination/status.json.")
    if not plan_input.merge_strategy.strip():
        gaps.append("Merge strategy is missing; record how parallel outputs will be combined and reviewed.")
    if not plan_input.communication_checkpoints:
        gaps.append("Communication checkpoints are missing; record when lanes report status and blockers.")
    if not plan_input.verification_steps:
        gaps.append("Verification steps are missing; record final checks after parallel outputs merge.")
    if not plan_input.rollback_plan:
        gaps.append("Rollback plan is missing; record how to recover if one lane fails or conflicts.")
    if not plan_input.source_value_provenance:
        gaps.append("Source value provenance is missing; record where dependency, concurrency, and conflict assumptions came from.")
    if not plan_input.plan_evidence:
        gaps.append("Plan evidence is missing; map lanes, dependencies, and merge choices to checked sources or repository evidence.")
    if not plan_input.plan_history_targets:
        gaps.append("Plan history target is missing.")

    batches = [] if cycle_path else _execution_batches(plan_input.tasks)
    _validate_batch_conflicts(batches, task_by_id, gaps)
    _validate_parallel_research_merge_gates(batches, task_by_id, plan_input.merge_gates, gaps)

    max_parallel_width = max((len(batch) for batch in batches), default=0)
    parallelism_available = max_parallel_width > 1
    if plan_input.tasks and not parallelism_available and not gaps:
        warnings.append("No independent task batch was found; execute sequentially or split work differently.")

    status = "rework_required" if gaps else "ready_to_parallelize" if parallelism_available else "sequential_required"

    return {
        "status": status,
        "requires_rework": bool(gaps),
        "parallelism_available": parallelism_available,
        "principle": "Parallel work needs explicit dependencies, file/resource boundaries, coordination, merge strategy, and final verification.",
        "checks": {
            "work_mode": work_mode,
            "tasks_count": len(plan_input.tasks),
            "merge_gates_count": len(plan_input.merge_gates),
            "parallelizable_tasks_count": len([task for task in plan_input.tasks if task.parallelizable]),
            "shared_resources_count": len(plan_input.shared_resources),
            "conflict_controls_count": len(plan_input.conflict_controls),
            "coordination_targets_count": len(plan_input.coordination_targets),
            "communication_checkpoints_count": len(plan_input.communication_checkpoints),
            "verification_steps_count": len(plan_input.verification_steps),
            "rollback_plan_count": len(plan_input.rollback_plan),
            "source_value_provenance_count": len(plan_input.source_value_provenance),
            "plan_evidence_count": len(plan_input.plan_evidence),
            "plan_history_targets_count": len(plan_input.plan_history_targets),
            "execution_batches_count": len(batches),
            "max_parallel_width": max_parallel_width,
        },
        "execution_batches": batches,
        "merge_gates": _merge_gate_summaries(plan_input.merge_gates, task_by_id, batches),
        "gaps": gaps,
        "warnings": warnings,
        "follow_up_actions": [f"Resolve gap: {gap}" for gap in gaps],
    }


def _validate_task_fields(tasks: tuple[ParallelWorkTask, ...], gaps: list[str]) -> None:
    for index, task in enumerate(tasks, start=1):
        label = task.task_id.strip() or f"task {index}"
        if not task.task_id.strip():
            gaps.append(f"{label} is missing task_id.")
        if not task.title.strip():
            gaps.append(f"{label} is missing title.")
        if not task.owner.strip():
            gaps.append(f"{label} is missing owner.")
        if not task.scope.strip():
            gaps.append(f"{label} is missing scope.")
        if not task.touch_paths:
            gaps.append(f"{label} is missing touch_paths.")
        if not task.output_targets:
            gaps.append(f"{label} is missing output_targets.")
        if not task.verification_steps:
            gaps.append(f"{label} is missing verification_steps.")
        if task.risk_level not in ALLOWED_RISK_LEVELS:
            gaps.append(f"{label} has unknown risk_level: {task.risk_level}.")


def _validate_dependencies(
    tasks: tuple[ParallelWorkTask, ...],
    task_by_id: dict[str, ParallelWorkTask],
    gaps: list[str],
) -> None:
    for task in tasks:
        task_id = task.task_id.strip()
        for dependency in task.dependencies:
            normalized_dependency = dependency.strip()
            if normalized_dependency == task_id:
                gaps.append(f"{task_id} cannot depend on itself.")
            elif normalized_dependency not in task_by_id:
                gaps.append(f"{task_id} depends on unknown task_id: {normalized_dependency}.")


def _validate_merge_gates(
    merge_gates: tuple[ParallelMergeGate, ...],
    task_by_id: dict[str, ParallelWorkTask],
    gaps: list[str],
) -> None:
    gate_ids = [gate.gate_id.strip() for gate in merge_gates]
    if len(set(gate_ids)) != len(gate_ids):
        gaps.append("Merge gate IDs must be unique.")

    for index, gate in enumerate(merge_gates, start=1):
        label = gate.gate_id.strip() or f"merge gate {index}"
        if not gate.gate_id.strip():
            gaps.append(f"{label} is missing gate_id.")
        if not gate.title.strip():
            gaps.append(f"{label} is missing title.")
        if len(gate.wait_for) < 2:
            gaps.append(f"{label} must wait for at least two upstream lanes.")
        if len(set(gate.wait_for)) != len(gate.wait_for):
            gaps.append(f"{label} wait_for task IDs must be unique.")
        if not gate.merge_task_id.strip():
            gaps.append(f"{label} is missing merge_task_id.")
        if gate.merge_task_id in gate.wait_for:
            gaps.append(f"{label} merge_task_id cannot also be in wait_for.")
        if not gate.merge_outputs:
            gaps.append(f"{label} is missing merge_outputs.")
        if not gate.acceptance_checks:
            gaps.append(f"{label} is missing acceptance_checks.")

        unknown_waits = [task_id for task_id in gate.wait_for if task_id not in task_by_id]
        if unknown_waits:
            gaps.append(f"{label} waits for unknown task_id: {', '.join(unknown_waits)}.")
        if gate.merge_task_id not in task_by_id:
            gaps.append(f"{label} references unknown merge_task_id: {gate.merge_task_id}.")
            continue

        merge_task = task_by_id[gate.merge_task_id]
        missing_dependencies = sorted(set(gate.wait_for) - set(merge_task.dependencies))
        if missing_dependencies:
            gaps.append(
                f"{label} merge task {gate.merge_task_id} must depend on all wait_for tasks; missing: "
                f"{', '.join(missing_dependencies)}."
            )


def _validate_parallel_research_merge_gates(
    batches: list[list[str]],
    task_by_id: dict[str, ParallelWorkTask],
    merge_gates: tuple[ParallelMergeGate, ...],
    gaps: list[str],
) -> None:
    gate_wait_sets = [set(gate.wait_for) for gate in merge_gates]
    for batch in batches:
        research_task_ids = [task_id for task_id in batch if _looks_like_research_task(task_by_id[task_id])]
        if len(research_task_ids) < 2:
            continue
        if not any(set(research_task_ids).issubset(wait_set) for wait_set in gate_wait_sets):
            gaps.append(
                "Parallel research lanes require a merge gate that waits for every research lane in the batch: "
                f"{', '.join(research_task_ids)}."
            )


def _find_cycle(tasks: tuple[ParallelWorkTask, ...]) -> list[str]:
    task_ids = {task.task_id.strip() for task in tasks if task.task_id.strip()}
    dependencies = {
        task.task_id.strip(): [dependency.strip() for dependency in task.dependencies if dependency.strip() in task_ids]
        for task in tasks
        if task.task_id.strip()
    }
    visiting: set[str] = set()
    visited: set[str] = set()
    stack: list[str] = []

    def visit(task_id: str) -> list[str]:
        if task_id in visiting:
            cycle_start = stack.index(task_id)
            return stack[cycle_start:] + [task_id]
        if task_id in visited:
            return []
        visiting.add(task_id)
        stack.append(task_id)
        for dependency in dependencies.get(task_id, []):
            cycle = visit(dependency)
            if cycle:
                return cycle
        stack.pop()
        visiting.remove(task_id)
        visited.add(task_id)
        return []

    for task_id in sorted(task_ids):
        cycle = visit(task_id)
        if cycle:
            return cycle
    return []


def _execution_batches(tasks: tuple[ParallelWorkTask, ...]) -> list[list[str]]:
    remaining = {task.task_id.strip(): set(dependency.strip() for dependency in task.dependencies if dependency.strip()) for task in tasks if task.task_id.strip()}
    task_by_id = {task.task_id.strip(): task for task in tasks if task.task_id.strip()}
    completed: set[str] = set()
    batches: list[list[str]] = []

    while remaining:
        ready = sorted(
            task_id
            for task_id, dependencies in remaining.items()
            if dependencies.issubset(completed) and task_by_id[task_id].parallelizable
        )
        if not ready:
            ready = sorted(task_id for task_id, dependencies in remaining.items() if dependencies.issubset(completed))[:1]
        if not ready:
            return []
        batches.append(ready)
        completed.update(ready)
        for task_id in ready:
            remaining.pop(task_id, None)
    return batches


def _merge_gate_summaries(
    merge_gates: tuple[ParallelMergeGate, ...],
    task_by_id: dict[str, ParallelWorkTask],
    batches: list[list[str]],
) -> list[JsonMap]:
    task_to_batch = {task_id: index for index, batch in enumerate(batches, start=1) for task_id in batch}
    summaries = []
    for gate in merge_gates:
        wait_batches = [task_to_batch[task_id] for task_id in gate.wait_for if task_id in task_to_batch]
        merge_batch = task_to_batch.get(gate.merge_task_id)
        summaries.append(
            {
                "gate_id": gate.gate_id,
                "title": gate.title,
                "wait_for": list(gate.wait_for),
                "merge_task_id": gate.merge_task_id,
                "wait_batches": sorted(set(wait_batches)),
                "merge_batch": merge_batch,
                "merge_outputs": list(gate.merge_outputs),
                "acceptance_checks": list(gate.acceptance_checks),
                "ready_after_batch": max(wait_batches) if wait_batches else None,
                "merge_task_known": gate.merge_task_id in task_by_id,
            }
        )
    return summaries


def _validate_batch_conflicts(
    batches: list[list[str]],
    task_by_id: dict[str, ParallelWorkTask],
    gaps: list[str],
) -> None:
    for batch in batches:
        if len(batch) < 2:
            continue
        for index, task_id in enumerate(batch):
            for other_task_id in batch[index + 1 :]:
                overlap = _overlapping_paths(task_by_id[task_id].touch_paths, task_by_id[other_task_id].touch_paths)
                if overlap:
                    gaps.append(
                        f"Parallel tasks {task_id} and {other_task_id} touch overlapping paths: {', '.join(overlap)}."
                    )


def _overlapping_paths(left_paths: tuple[str, ...], right_paths: tuple[str, ...]) -> list[str]:
    overlaps = []
    normalized_left = [_normalize_path(path) for path in left_paths if path.strip()]
    normalized_right = [_normalize_path(path) for path in right_paths if path.strip()]
    for left in normalized_left:
        for right in normalized_right:
            if left == right or left.startswith(f"{right}/") or right.startswith(f"{left}/"):
                overlaps.append(f"{left} <-> {right}")
    return sorted(set(overlaps))


def _looks_like_research_task(task: ParallelWorkTask) -> bool:
    searchable = " ".join([task.task_id, task.title, task.owner, task.scope]).lower()
    return "research" in searchable or "조사" in searchable or "리서치" in searchable


def _normalize_path(path: str) -> str:
    return path.strip().replace("\\", "/").rstrip("/")


def _required_string(data: JsonMap, field_name: str) -> str:
    value = data.get(field_name)
    if not isinstance(value, str):
        raise TypeError(f"{field_name} must be a string.")
    return value


def _optional_string(value: Any, field_name: str) -> str:
    if not isinstance(value, str):
        raise TypeError(f"{field_name} must be a string.")
    return value


def _optional_bool(value: Any, field_name: str) -> bool:
    if not isinstance(value, bool):
        raise TypeError(f"{field_name} must be a bool.")
    return value


def _tuple_of_strings(value: Any, field_name: str) -> tuple[str, ...]:
    if not isinstance(value, list | tuple):
        raise TypeError(f"{field_name} must be a list of strings.")
    if not all(isinstance(item, str) for item in value):
        raise TypeError(f"{field_name} must contain only strings.")
    return tuple(value)


def _list_of_maps(value: Any, field_name: str) -> list[JsonMap]:
    if not isinstance(value, list):
        raise TypeError(f"{field_name} must be a list.")
    if not all(isinstance(item, dict) for item in value):
        raise TypeError(f"{field_name} must contain only objects.")
    return value

"""Turn search findings into validated insights and plan readiness."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any


JsonMap = dict[str, Any]

REQUIRED_ANSWER_ENGINE_STAGES = {
