        )


def create_research_insight_plan(plan_input: ResearchInsightPlanInput) -> JsonMap:
    """Return a readiness report for search-backed planning."""

    gaps = []
    warnings = []

    if not plan_input.objective.strip():
        gaps.append("Objective is missing.")
    if not plan_input.search_questions:
        gaps.append("Search questions are missing.")
    if len(plan_input.search_channels) < 2:
        gaps.append("Use at least two search channels, such as web search plus repository or documentation search.")
    if plan_input.search_channels and not _has_web_channel(plan_input.search_channels):
        gaps.append("Web search channel is missing.")
    if not plan_input.sources_checked:
        gaps.append("Sources checked are missing.")
    if not plan_input.research_profile_paths:
        gaps.append("Research profile paths are missing; record the research/source configs used for this plan.")
    elif not any(_is_research_config_path(path) for path in plan_input.research_profile_paths):
        gaps.append("At least one research profile path must point to agent-platform/configs/research/.")
    if not plan_input.answer_engine_stages:
        gaps.append("Answer engine stages are missing; use the research-agent-profile pipeline before planning.")
    else:
        missing_stages = sorted(REQUIRED_ANSWER_ENGINE_STAGES - _normalized_stage_ids(plan_input.answer_engine_stages))
        if missing_stages:
            gaps.append(f"Answer engine stages are incomplete; missing: {', '.join(missing_stages)}.")
    if not plan_input.citation_requirements:
        gaps.append("Citation requirements are missing; record how claims will be grounded to checked sources.")
    if not plan_input.source_value_provenance:
        gaps.append("Source value provenance is missing; record where material values, assumptions, claims, or constraints came from.")
    if not plan_input.plan_evidence:
        gaps.append("Plan evidence is missing; map each material plan step to checked sources, repository evidence, or explicit assumptions.")
    if not plan_input.insights:
        gaps.append("Insights are missing.")
    if not plan_input.plan_steps:
        gaps.append("Plan steps are missing.")
    elif plan_input.plan_evidence and len(plan_input.plan_evidence) < len(plan_input.plan_steps):
        gaps.append("Each material plan step needs supporting plan_evidence.")
    if not plan_input.validation_steps:
        gaps.append("Validation steps are missing.")
    if not plan_input.plan_history_targets:
        gaps.append("Plan history target is missing.")

    if _uses_internal_knowledge(plan_input.sources_checked) and plan_input.knowledge_validation_status != "ready_to_reference":
        gaps.append("Internal knowledge-base sources require knowledge_validation_status=ready_to_reference.")

    if not plan_input.risks_or_unknowns:
        warnings.append("Risks or unknowns are missing; record uncertainty before execution.")
    if not plan_input.capture_targets:
        warnings.append("Capture targets are missing; record where reusable findings should be stored.")

    status = "more_research_required" if gaps else "ready_to_plan"

    return {
        "status": status,
        "requires_more_research": bool(gaps),
        "principle": "Use a search-grounded answer-engine flow to produce evidence-backed insights before planning.",
        "checks": {
            "search_questions_count": len(plan_input.search_questions),
            "search_channels_count": len(plan_input.search_channels),
            "sources_checked_count": len(plan_input.sources_checked),
            "research_profile_paths_count": len(plan_input.research_profile_paths),
            "answer_engine_stages_count": len(plan_input.answer_engine_stages),
            "required_answer_engine_stages": sorted(REQUIRED_ANSWER_ENGINE_STAGES),
            "citation_requirements_count": len(plan_input.citation_requirements),
            "source_value_provenance_count": len(plan_input.source_value_provenance),
            "plan_evidence_count": len(plan_input.plan_evidence),
            "insights_count": len(plan_input.insights),
            "plan_steps_count": len(plan_input.plan_steps),
            "validation_steps_count": len(plan_input.validation_steps),
            "risks_or_unknowns_count": len(plan_input.risks_or_unknowns),
            "capture_targets_count": len(plan_input.capture_targets),
            "plan_history_targets_count": len(plan_input.plan_history_targets),
        },
        "gaps": gaps,
        "warnings": warnings,
        "follow_up_actions": [f"Resolve gap: {gap}" for gap in gaps],
    }


def _has_web_channel(search_channels: tuple[str, ...]) -> bool:
    return any("web" in channel.lower() or "internet" in channel.lower() for channel in search_channels)


def _uses_internal_knowledge(sources_checked: tuple[str, ...]) -> bool:
    internal_prefixes = ("_research/", "_docs/", "_history/", "_ops/", "agent-platform/docs/")
    internal_files = ("AGENTS.md", "README.md")
    return any(source.startswith(internal_prefixes) or source in internal_files for source in sources_checked)


def _is_research_config_path(path: str) -> bool:
    normalized = path.strip().replace("\\", "/")
    return normalized.startswith("agent-platform/configs/research/") and normalized.endswith(".json")


def _normalized_stage_ids(stage_ids: tuple[str, ...]) -> set[str]:
    return {stage_id.strip().lower().replace("-", "_").replace(" ", "_") for stage_id in stage_ids if stage_id.strip()}


def _required_string(data: JsonMap, field_name: str) -> str:
    value = data.get(field_name)
    if not isinstance(value, str):
        raise TypeError(f"{field_name} must be a string.")
    return value


def _optional_string(value: Any, field_name: str) -> str:
    if not isinstance(value, str):
        raise TypeError(f"{field_name} must be a string.")
    return value


def _tuple_of_strings(value: Any, field_name: str) -> tuple[str, ...]:
    if not isinstance(value, list | tuple):
        raise TypeError(f"{field_name} must be a list of strings.")
    if not all(isinstance(item, str) for item in value):
        raise TypeError(f"{field_name} must contain only strings.")
    return tuple(value)

"""Decide whether spec/source drift needs spec change, source change, or user clarification."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any


JsonMap = dict[str, Any]

ALLOWED_ISSUE_TYPES = {
    "ambiguous_spec",
    "spec_source_mismatch",
    "missing_spec",
    "missing_source_trace",
    "test_disagreement",
}
ALLOWED_RESOLUTIONS = {"update_spec", "update_source", "ask_user", "defer"}
ALLOWED_SEVERITIES = {"info": 10, "warning": 20, "error": 30, "critical": 40}


@dataclass(frozen=True)
class ClarificationQuestion:
    """One user-answerable question needed before changing spec or source."""

    question_id: str
    question: str
    options: tuple[str, ...] = ()
    recommended_option: str = ""
    answer_format: str = ""
    decision_impact: str = ""

    @classmethod
    def from_dict(cls, data: JsonMap) -> "ClarificationQuestion":
        return cls(
            question_id=_required_string(data, "question_id"),
            question=_required_string(data, "question"),
            options=_tuple_of_strings(data.get("options", []), "options"),
            recommended_option=_optional_string(data.get("recommended_option", ""), "recommended_option"),
            answer_format=_optional_string(data.get("answer_format", ""), "answer_format"),
            decision_impact=_optional_string(data.get("decision_impact", ""), "decision_impact"),
        )


@dataclass(frozen=True)
class SpecSourceIssue:
    """One ambiguity or mismatch between a project spec and current source."""

    issue_id: str
    issue_type: str
    summary: str
    severity: str = "warning"
    affected_spec_refs: tuple[str, ...] = ()
    affected_source_paths: tuple[str, ...] = ()
    observed_spec_behavior: str = ""
    observed_source_behavior: str = ""
    evidence: tuple[str, ...] = ()
    default_resolution: str = "ask_user"
    questions: tuple[ClarificationQuestion, ...] = ()

    @classmethod
    def from_dict(cls, data: JsonMap) -> "SpecSourceIssue":
        return cls(
            issue_id=_required_string(data, "issue_id"),
            issue_type=_required_string(data, "issue_type"),
            summary=_required_string(data, "summary"),
            severity=_optional_string(data.get("severity", "warning"), "severity"),
            affected_spec_refs=_tuple_of_strings(data.get("affected_spec_refs", []), "affected_spec_refs"),
            affected_source_paths=_tuple_of_strings(data.get("affected_source_paths", []), "affected_source_paths"),
            observed_spec_behavior=_optional_string(data.get("observed_spec_behavior", ""), "observed_spec_behavior"),
            observed_source_behavior=_optional_string(data.get("observed_source_behavior", ""), "observed_source_behavior"),
            evidence=_tuple_of_strings(data.get("evidence", []), "evidence"),
            default_resolution=_optional_string(data.get("default_resolution", "ask_user"), "default_resolution"),
            questions=tuple(
                ClarificationQuestion.from_dict(item) for item in _list_of_maps(data.get("questions", []), "questions")
            ),
        )


@dataclass(frozen=True)
class SpecReconciliationInput:
    """Input for deciding how to reconcile spec ambiguity or spec/source drift."""

    project: str
    request_summary: str
    spec_paths: tuple[str, ...] = ()
    source_paths: tuple[str, ...] = ()
    comparison_evidence: tuple[str, ...] = ()
    issues: tuple[SpecSourceIssue, ...] = ()
    notification_targets: tuple[str, ...] = ()
    decision_deadline: str = ""
    plan_history_targets: tuple[str, ...] = ()

    @classmethod
    def from_dict(cls, data: JsonMap) -> "SpecReconciliationInput":
        return cls(
            project=_required_string(data, "project"),
            request_summary=_required_string(data, "request_summary"),
            spec_paths=_tuple_of_strings(data.get("spec_paths", []), "spec_paths"),
            source_paths=_tuple_of_strings(data.get("source_paths", []), "source_paths"),
            comparison_evidence=_tuple_of_strings(data.get("comparison_evidence", []), "comparison_evidence"),
            issues=tuple(SpecSourceIssue.from_dict(item) for item in _list_of_maps(data.get("issues", []), "issues")),
            notification_targets=_tuple_of_strings(data.get("notification_targets", []), "notification_targets"),
            decision_deadline=_optional_string(data.get("decision_deadline", ""), "decision_deadline"),
            plan_history_targets=_tuple_of_strings(data.get("plan_history_targets", []), "plan_history_targets"),
        )


def reconcile_spec_source(reconciliation_input: SpecReconciliationInput) -> JsonMap:
    """Return a deterministic reconciliation and clarification report."""

    gaps: list[str] = []
    warnings: list[str] = []

    if not reconciliation_input.project.strip():
        gaps.append("Project is missing.")
    if not reconciliation_input.request_summary.strip():
        gaps.append("Request summary is missing.")
    has_missing_spec_issue = any(issue.issue_type == "missing_spec" for issue in reconciliation_input.issues)

    if not reconciliation_input.spec_paths and not has_missing_spec_issue:
        gaps.append("Spec paths are missing; compare against an active spec or record missing_spec as an issue.")
    if not reconciliation_input.source_paths:
        gaps.append("Source paths are missing; compare against current implementation, tests, or generated artifacts.")
    if not reconciliation_input.comparison_evidence:
        gaps.append("Comparison evidence is missing; record inspected spec lines, source paths, tests, or command outputs.")
    if not reconciliation_input.issues:
        gaps.append("Issues are missing; record at least one ambiguity, mismatch, or missing trace.")
    if not reconciliation_input.plan_history_targets:
        warnings.append("Plan history targets are missing; save the reconciliation plan for meaningful work.")

    for issue in reconciliation_input.issues:
        _validate_issue(issue, gaps, warnings)

    clarification_issues = tuple(
        issue
        for issue in reconciliation_input.issues
        if issue.default_resolution == "ask_user" or issue.issue_type == "ambiguous_spec"
    )
    spec_update_candidates = tuple(issue.issue_id for issue in reconciliation_input.issues if issue.default_resolution == "update_spec")
    source_update_candidates = tuple(
        issue.issue_id for issue in reconciliation_input.issues if issue.default_resolution == "update_source"
    )

    notification_event = _build_notification_event(reconciliation_input, clarification_issues) if clarification_issues else None

    if gaps:
        status = "rework_required"
    elif clarification_issues:
        status = "clarification_required"
    else:
        status = "ready_to_reconcile"

    follow_up_actions = [f"Resolve reconciliation gap: {gap}" for gap in gaps]
    if status == "clarification_required":
        follow_up_actions.append("Send or surface notification_event so the user can answer the listed question IDs.")
        follow_up_actions.append("Do not change spec or source for ask_user issues until the answer is recorded.")
    if spec_update_candidates:
        follow_up_actions.append("For update_spec candidates, update spec and traceability before changing implementation behavior.")
    if source_update_candidates:
        follow_up_actions.append("For update_source candidates, update source/tests and validation against the active spec.")

    return {
        "status": status,
        "requires_rework": bool(gaps),
        "requires_user_input": status == "clarification_required",
        "principle": "When spec and source disagree, inspect evidence first, classify whether the spec or source should change, and ask user-answerable questions for ambiguous decisions.",
        "checks": {
            "spec_paths_count": len(reconciliation_input.spec_paths),
            "source_paths_count": len(reconciliation_input.source_paths),
            "comparison_evidence_count": len(reconciliation_input.comparison_evidence),
            "issues_count": len(reconciliation_input.issues),
            "clarification_questions_count": sum(len(issue.questions) for issue in clarification_issues),
            "notification_targets_count": len(reconciliation_input.notification_targets),
        },
        "spec_update_candidates": spec_update_candidates,
        "source_update_candidates": source_update_candidates,
        "clarification_issue_ids": tuple(issue.issue_id for issue in clarification_issues),
        "notification_event": notification_event,
        "gaps": gaps,
        "warnings": warnings,
        "follow_up_actions": follow_up_actions,
    }


def _validate_issue(issue: SpecSourceIssue, gaps: list[str], warnings: list[str]) -> None:
    label = f"issue {issue.issue_id}"
    if issue.issue_type not in ALLOWED_ISSUE_TYPES:
        gaps.append(f"{label} has unknown issue_type: {issue.issue_type}.")
    if issue.default_resolution not in ALLOWED_RESOLUTIONS:
        gaps.append(f"{label} has unknown default_resolution: {issue.default_resolution}.")
    if issue.severity not in ALLOWED_SEVERITIES:
        gaps.append(f"{label} has unknown severity: {issue.severity}.")
    if not issue.evidence:
        gaps.append(f"{label} is missing evidence.")
    if issue.issue_type == "spec_source_mismatch" and not (
        issue.observed_spec_behavior.strip() and issue.observed_source_behavior.strip()
    ):
        gaps.append(f"{label} must record observed_spec_behavior and observed_source_behavior.")
    if issue.default_resolution == "update_spec" and not issue.affected_spec_refs:
        gaps.append(f"{label} is marked update_spec but has no affected_spec_refs.")
    if issue.default_resolution == "update_source" and not issue.affected_source_paths:
        gaps.append(f"{label} is marked update_source but has no affected_source_paths.")
    if (issue.default_resolution == "ask_user" or issue.issue_type == "ambiguous_spec") and not issue.questions:
        gaps.append(f"{label} requires user clarification but has no questions.")
    for question in issue.questions:
        _validate_question(question, label, gaps, warnings)


def _validate_question(
    question: ClarificationQuestion,
    issue_label: str,
    gaps: list[str],
    warnings: list[str],
) -> None:
    label = f"{issue_label} question {question.question_id}"
    if not question.question_id.strip():
        gaps.append(f"{label} has an empty question_id.")
    if not question.question.strip():
        gaps.append(f"{label} has an empty question.")
    if not question.answer_format.strip():
        gaps.append(f"{label} is missing answer_format.")
    if question.options and question.recommended_option and question.recommended_option not in question.options:
        gaps.append(f"{label} recommended_option must match one of options.")
    if not question.decision_impact.strip():
        warnings.append(f"{label} has no decision_impact.")


def _build_notification_event(
    reconciliation_input: SpecReconciliationInput,
    clarification_issues: tuple[SpecSourceIssue, ...],
) -> JsonMap:
    severity = _max_severity(issue.severity for issue in clarification_issues)
    question_lines: list[str] = []
    reply_lines: list[str] = []
    for issue in clarification_issues:
        question_lines.append(f"- {issue.issue_id}: {issue.summary}")
        for question in issue.questions:
            option_text = f" Options: {', '.join(question.options)}." if question.options else ""
            recommendation = f" Recommended: {question.recommended_option}." if question.recommended_option else ""
            question_lines.append(f"  - {question.question_id}: {question.question}{option_text}{recommendation}")
            reply_lines.append(question.answer_format or f"{question.question_id}=<answer>")

    deadline = f"\nDeadline: {reconciliation_input.decision_deadline}" if reconciliation_input.decision_deadline else ""
    message = "\n".join(
        [
            f"Project: {reconciliation_input.project}",
            f"Request: {reconciliation_input.request_summary}",
            "Spec/source reconciliation needs your decision before continuing.",
            "Questions:",
            *question_lines,
            "Reply format:",
            *reply_lines,
            deadline.strip(),
        ]
    ).strip()
    return {
        "event_type": "clarification_needed",
        "title": f"Spec clarification needed: {reconciliation_input.project}",
        "message": message,
        "severity": severity,
        "metadata": {
            "project": reconciliation_input.project,
            "question_ids": ",".join(question.question_id for issue in clarification_issues for question in issue.questions),
            "spec_paths": ",".join(reconciliation_input.spec_paths),
            "source_paths": ",".join(reconciliation_input.source_paths),
        },
    }


def _max_severity(values: Any) -> str:
    max_value = "info"
    for value in values:
        if value in ALLOWED_SEVERITIES and ALLOWED_SEVERITIES[value] > ALLOWED_SEVERITIES[max_value]:
            max_value = value
    return max_value


def _required_string(data: JsonMap, field_name: str) -> str:
    value = data.get(field_name)
    if not isinstance(value, str):
        raise TypeError(f"{field_name} must be a string.")
    return value


def _optional_string(value: Any, field_name: str) -> str:
    if not isinstance(value, str):
        raise TypeError(f"{field_name} must be a string.")
    return value


def _tuple_of_strings(value: Any, field_name: str) -> tuple[str, ...]:
    if not isinstance(value, list | tuple):
        raise TypeError(f"{field_name} must be a list of strings.")
    if not all(isinstance(item, str) for item in value):
        raise TypeError(f"{field_name} must contain only strings.")
    return tuple(value)


def _list_of_maps(value: Any, field_name: str) -> list[JsonMap]:
    if not isinstance(value, list):
        raise TypeError(f"{field_name} must be a list.")
    if not all(isinstance(item, dict) for item in value):
        raise TypeError(f"{field_name} must contain only objects.")
    return value

"""View mode registry helpers."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any


REQUIRED_MODE_IDS = {"user", "developer", "superadmin_developer"}

REQUIRED_TOP_LEVEL_FIELDS = {
    "schema_version",
    "name",
    "purpose",
    "reader_guide",
    "reference_links",
    "structure_rules",
    "field_guide",
    "mode_boundary",
    "default_mode",
    "modes",
    "selection_rules",
}

REQUIRED_MODE_FIELDS = {
    "id",
    "label",
    "intent",
    "audience",
    "visibility_rules",
    "allowed_sections",
    "must_not",
    "security_notes",
}

REQUIRED_VISIBILITY_FIELDS = {"foreground", "collapse", "hide_by_default", "guard"}
REQUIRED_MODE_BOUNDARY_FIELDS = {"view_mode", "install_mode", "work_mode", "rule"}
USER_REQUIRED_SECTIONS = {"overview", "agents", "desktop", "source", "intent"}
SUPERADMIN_REQUIRED_SECTIONS = {
    "overview",
    "projects",
    "history",
    "structure",
    "documents",
    "requirements",
    "agents",
}


def load_view_mode_registry(path: Path) -> dict[str, Any]:
    """Load a view mode registry JSON file."""

    with path.open("r", encoding="utf-8") as file:
        data = json.load(file)
    if not isinstance(data, dict):
        raise ValueError("View mode registry must be a JSON object.")
    return data


def list_view_modes(registry: dict[str, Any]) -> list[dict[str, str]]:
    """Return compact view mode records."""

    return [
        {
            "id": mode["id"],
            "label": mode["label"],
            "intent": mode["intent"],
        }
        for mode in _mode_records(registry)
    ]


def show_view_mode(registry: dict[str, Any], mode_id: str) -> dict[str, Any]:
    """Return one view mode by id."""

    for mode in _mode_records(registry):
        if mode.get("id") == mode_id:
            return mode
    raise ValueError(f"Unknown view mode '{mode_id}'.")


def check_view_mode_registry(registry: dict[str, Any]) -> dict[str, Any]:
    """Validate the registry shape and user/developer/superadmin split."""

    gaps: list[str] = []
    warnings: list[str] = []

    missing = sorted(REQUIRED_TOP_LEVEL_FIELDS - set(registry))
    if missing:
        gaps.append(f"Missing top-level fields: {', '.join(missing)}.")

    _check_mode_boundary(registry, gaps)

    modes = registry.get("modes")
    if not isinstance(modes, list) or not modes:
        gaps.append("modes must be a non-empty list.")
        modes = []

    mode_ids: list[str] = []
    for index, mode in enumerate(modes, start=1):
        if not isinstance(mode, dict):
            gaps.append(f"modes[{index}] must be an object.")
            continue

        mode_id = str(mode.get("id", "")).strip()
        if mode_id:
            mode_ids.append(mode_id)

        missing_mode_fields = sorted(REQUIRED_MODE_FIELDS - set(mode))
        if missing_mode_fields:
            gaps.append(f"mode {mode_id or index}: missing fields: {', '.join(missing_mode_fields)}.")

        _check_visibility_rules(mode, mode_id or str(index), gaps)
        _check_allowed_sections(mode, mode_id or str(index), gaps, warnings)
        _check_string_lists(mode, mode_id or str(index), gaps)

    if set(mode_ids) != REQUIRED_MODE_IDS:
        gaps.append(
            "View mode ids must be exactly: "
            f"{', '.join(sorted(REQUIRED_MODE_IDS))}. Found: {', '.join(sorted(mode_ids))}."
        )
    if len(mode_ids) != len(set(mode_ids)):
        gaps.append("View mode ids must be unique.")

    default_mode = registry.get("default_mode")
    if default_mode not in mode_ids:
        gaps.append("default_mode must match one modes[].id.")
    if default_mode != "superadmin_developer":
        warnings.append("Current default_mode should stay superadmin_developer until the owner changes the operating default.")

    selection_rules = registry.get("selection_rules")
    if not isinstance(selection_rules, list) or not selection_rules:
        gaps.append("selection_rules must be a non-empty list.")
    elif not any("install_mode" in str(rule) and "work_mode" in str(rule) for rule in selection_rules):
        warnings.append("selection_rules should explicitly keep view_mode separate from install_mode and work_mode.")

    return {
        "status": "ready" if not gaps else "rework_required",
        "requires_rework": bool(gaps),
        "checks": {
            "mode_count": len(mode_ids),
            "mode_ids": mode_ids,
            "default_mode": default_mode,
            "required_mode_ids": sorted(REQUIRED_MODE_IDS),
        },
        "gaps": gaps,
        "warnings": warnings,
        "follow_up_actions": [f"Resolve gap: {gap}" for gap in gaps],
    }


def _check_mode_boundary(registry: dict[str, Any], gaps: list[str]) -> None:
    boundary = registry.get("mode_boundary")
    if not isinstance(boundary, dict):
        gaps.append("mode_boundary must be an object.")
        return
    missing = sorted(REQUIRED_MODE_BOUNDARY_FIELDS - set(boundary))
    if missing:
        gaps.append(f"mode_boundary is missing fields: {', '.join(missing)}.")


def _check_visibility_rules(mode: dict[str, Any], mode_id: str, gaps: list[str]) -> None:
    rules = mode.get("visibility_rules")
    if not isinstance(rules, dict):
        gaps.append(f"mode {mode_id}: visibility_rules must be an object.")
        return

    missing = sorted(REQUIRED_VISIBILITY_FIELDS - set(rules))
    if missing:
        gaps.append(f"mode {mode_id}: visibility_rules missing fields: {', '.join(missing)}.")

    for field in REQUIRED_VISIBILITY_FIELDS:
        values = rules.get(field)
        if not isinstance(values, list):
            gaps.append(f"mode {mode_id}: visibility_rules.{field} must be a list.")
            continue
        if not all(isinstance(item, str) for item in values):
            gaps.append(f"mode {mode_id}: visibility_rules.{field} must contain only strings.")


def _check_allowed_sections(
    mode: dict[str, Any],
    mode_id: str,
    gaps: list[str],
    warnings: list[str],
) -> None:
    sections = mode.get("allowed_sections")
    if not isinstance(sections, list) or not sections:
        gaps.append(f"mode {mode_id}: allowed_sections must be a non-empty list.")
        return
    if not all(isinstance(section, str) for section in sections):
        gaps.append(f"mode {mode_id}: allowed_sections must contain only strings.")
        return

    missing_required = sorted(USER_REQUIRED_SECTIONS - set(sections))
    if mode_id == "user" and missing_required:
        gaps.append(f"mode {mode_id}: user view must include sections: {', '.join(missing_required)}.")

    if mode_id == "superadmin_developer":
        missing_superadmin = sorted(SUPERADMIN_REQUIRED_SECTIONS - set(sections))
        if missing_superadmin:
            gaps.append(
                f"mode {mode_id}: superadmin developer view must include sections: "
                f"{', '.join(missing_superadmin)}."
            )
    if mode_id == "developer" and "requirements" not in sections:
        warnings.append("mode developer should include requirements for traceability work.")


def _check_string_lists(mode: dict[str, Any], mode_id: str, gaps: list[str]) -> None:
    for field in ("audience", "must_not", "security_notes"):
        values = mode.get(field)
        if not isinstance(values, list) or not values:
            gaps.append(f"mode {mode_id}: {field} must be a non-empty list.")
            continue
        if not all(isinstance(item, str) for item in values):
            gaps.append(f"mode {mode_id}: {field} must contain only strings.")


def _mode_records(registry: dict[str, Any]) -> list[dict[str, Any]]:
    modes = registry.get("modes", [])
    if not isinstance(modes, list):
        raise ValueError("modes must be a list.")
    return [mode for mode in modes if isinstance(mode, dict)]

"""Work mode registry helpers and enforcement checks."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from agent_platform.evaluation.work_evaluator import MODE_REQUIRED_TARGETS, TARGET_GAP_MESSAGES


REQUIRED_MODE_IDS = {"quick", "standard", "ship_first", "research", "governance"}

REQUIRED_TOP_LEVEL_FIELDS = {
    "schema_version",
    "name",
    "purpose",
    "reader_guide",
    "reference_links",
    "structure_rules",
    "field_guide",
    "mode_enforcement",
    "default_mode",
    "modes",
    "selection_rules",
    "evaluator_policy",
    "deferred_improvement_rules",
}

REQUIRED_MODE_FIELDS = {
    "id",
    "label",
    "intent",
    "use_when",
    "avoid_when",
    "required_before_close",
    "deferred_or_optional",
    "enforcement_level",
    "selection_record_required",
    "closeout_gate",
}

REQUIRED_ENFORCEMENT_LAYERS = {
    "registry_config",
    "cli_registry_check",
    "mode_selection_record",
    "omission_coverage_record",
    "resource_leak_record",
    "cli_pipeline_record",
    "work_evaluator_gate",
    "evaluation_report",
}

ALLOWED_CLOSEOUT_REFERENCES = set(TARGET_GAP_MESSAGES) | {
    "initial_instruction",
    "result_summary",
    "changed_files_or_no_file_explanation",
    "verification",
    "verification_or_manual_check",
    "deferred_improvement_targets_when_improvement_ideas_exist",
    "resource_check_targets_when_resource_risk_occurred",
    "cli_pipeline_targets_when_cli_pipeline_occurred",
}


def load_work_mode_registry(path: Path) -> dict[str, Any]:
    """Load a work mode registry JSON file."""

    with path.open("r", encoding="utf-8") as file:
        data = json.load(file)
    if not isinstance(data, dict):
        raise ValueError("Work mode registry must be a JSON object.")
    return data


def list_work_modes(registry: dict[str, Any]) -> list[dict[str, Any]]:
    """Return compact work mode records."""

    return [
        {
            "id": mode["id"],
            "label": mode["label"],
            "intent": mode["intent"],
            "enforcement_level": mode.get("enforcement_level", "unknown"),
        }
        for mode in _mode_records(registry)
    ]


def show_work_mode(registry: dict[str, Any], mode_id: str) -> dict[str, Any]:
    """Return one work mode by id."""

    for mode in _mode_records(registry):
        if mode.get("id") == mode_id:
            return mode
    raise ValueError(f"Unknown work mode '{mode_id}'.")


def check_work_mode_registry(registry: dict[str, Any]) -> dict[str, Any]:
    """Validate that work modes are enforceable and aligned with evaluator policy."""

    gaps: list[str] = []
    warnings: list[str] = []

    missing = sorted(REQUIRED_TOP_LEVEL_FIELDS - set(registry))
    if missing:
        gaps.append(f"Missing top-level fields: {', '.join(missing)}.")

    modes = registry.get("modes")
    if not isinstance(modes, list) or not modes:
        gaps.append("modes must be a non-empty list.")
        modes = []

    mode_ids: list[str] = []
    for index, mode in enumerate(modes, start=1):
        if not isinstance(mode, dict):
            gaps.append(f"modes[{index}] must be an object.")
            continue

        mode_id = str(mode.get("id", "")).strip()
        if mode_id:
            mode_ids.append(mode_id)
        missing_mode_fields = sorted(REQUIRED_MODE_FIELDS - set(mode))
        if missing_mode_fields:
            gaps.append(f"mode {mode_id or index}: missing fields: {', '.join(missing_mode_fields)}.")

        _check_mode_lists(mode, mode_id or str(index), gaps)
        _check_mode_enforcement(mode, mode_id or str(index), gaps, warnings)

    if set(mode_ids) != REQUIRED_MODE_IDS:
        gaps.append(
            "Work mode ids must be exactly: "
            f"{', '.join(sorted(REQUIRED_MODE_IDS))}. Found: {', '.join(sorted(mode_ids))}."
        )
    if len(mode_ids) != len(set(mode_ids)):
        gaps.append("Work mode ids must be unique.")

    default_mode = registry.get("default_mode")
    if default_mode not in mode_ids:
        gaps.append("default_mode must match one modes[].id.")

    _check_mode_enforcement_block(registry, gaps)
    _check_evaluator_policy(registry, set(mode_ids), gaps, warnings)

    return {
        "status": "ready" if not gaps else "rework_required",
        "requires_rework": bool(gaps),
        "checks": {
            "mode_count": len(mode_ids),
            "mode_ids": mode_ids,
            "default_mode": default_mode,
            "required_enforcement_layers": sorted(REQUIRED_ENFORCEMENT_LAYERS),
            "evaluator_policy_modes": sorted((registry.get("evaluator_policy") or {}).keys())
            if isinstance(registry.get("evaluator_policy"), dict)
            else [],
        },
        "gaps": gaps,
        "warnings": warnings,
        "follow_up_actions": [f"Resolve gap: {gap}" for gap in gaps],
    }


def _check_mode_lists(mode: dict[str, Any], mode_id: str, gaps: list[str]) -> None:
    for field in ("use_when", "avoid_when", "required_before_close", "deferred_or_optional"):
        values = mode.get(field)
        if not isinstance(values, list):
            gaps.append(f"mode {mode_id}: {field} must be a list.")
            continue
        if not all(isinstance(item, str) for item in values):
            gaps.append(f"mode {mode_id}: {field} must contain only strings.")

    closeout_refs = mode.get("required_before_close", [])
    if isinstance(closeout_refs, list):
        unknown = sorted({item for item in closeout_refs if isinstance(item, str)} - ALLOWED_CLOSEOUT_REFERENCES)
        if unknown:
            gaps.append(f"mode {mode_id}: required_before_close contains unknown close-out references: {', '.join(unknown)}.")


def _check_mode_enforcement(
    mode: dict[str, Any],
    mode_id: str,
    gaps: list[str],
    warnings: list[str],
) -> None:
    enforcement_level = mode.get("enforcement_level")
    if enforcement_level not in {"advisory", "blocking"}:
        gaps.append(f"mode {mode_id}: enforcement_level must be advisory or blocking.")

    if not isinstance(mode.get("selection_record_required"), bool):
        gaps.append(f"mode {mode_id}: selection_record_required must be a boolean.")

    closeout_gate = mode.get("closeout_gate")
    if not isinstance(closeout_gate, str) or not closeout_gate.strip():
        gaps.append(f"mode {mode_id}: closeout_gate must be a non-empty string.")

    if mode_id != "quick" and mode.get("selection_record_required") is not True:
        gaps.append(f"mode {mode_id}: selection_record_required must be true for enforceable modes.")
    if mode_id != "quick" and enforcement_level != "blocking":
        gaps.append(f"mode {mode_id}: enforcement_level must be blocking for non-quick modes.")
    if mode_id == "quick" and enforcement_level != "advisory":
        warnings.append("mode quick should normally stay advisory to preserve low-friction tiny fixes.")


def _check_mode_enforcement_block(registry: dict[str, Any], gaps: list[str]) -> None:
    enforcement = registry.get("mode_enforcement")
    if not isinstance(enforcement, dict):
        gaps.append("mode_enforcement must be an object.")
        return

    layers = enforcement.get("layers")
    if not isinstance(layers, list) or not layers:
        gaps.append("mode_enforcement.layers must be a non-empty list.")
        return

    layer_ids = {
        str(layer.get("id", "")).strip()
        for layer in layers
        if isinstance(layer, dict) and str(layer.get("id", "")).strip()
    }
    missing_layers = sorted(REQUIRED_ENFORCEMENT_LAYERS - layer_ids)
    if missing_layers:
        gaps.append(f"mode_enforcement.layers is missing required layers: {', '.join(missing_layers)}.")

    for index, layer in enumerate(layers, start=1):
        if not isinstance(layer, dict):
            gaps.append(f"mode_enforcement.layers[{index}] must be an object.")
            continue
        for field in ("id", "purpose", "enforced_by"):
            if not isinstance(layer.get(field), str) or not layer[field].strip():
                gaps.append(f"mode_enforcement layer {layer.get('id', index)}: {field} must be a non-empty string.")


def _check_evaluator_policy(
    registry: dict[str, Any],
    mode_ids: set[str],
    gaps: list[str],
    warnings: list[str],
) -> None:
    policy = registry.get("evaluator_policy")
    if not isinstance(policy, dict):
        gaps.append("evaluator_policy must be an object.")
        return

    policy_ids = set(policy)
    if policy_ids != mode_ids:
        gaps.append(
            "evaluator_policy keys must match modes[].id. "
            f"mode ids={', '.join(sorted(mode_ids))}; policy ids={', '.join(sorted(policy_ids))}."
        )

    for mode_id, mode_policy in policy.items():
        if not isinstance(mode_policy, dict):
            gaps.append(f"evaluator_policy.{mode_id} must be an object.")
            continue
        blocking = _string_set(mode_policy.get("blocking_target_fields"), f"evaluator_policy.{mode_id}.blocking_target_fields", gaps)
        non_blocking = _string_set(
            mode_policy.get("non_blocking_target_fields"),
            f"evaluator_policy.{mode_id}.non_blocking_target_fields",
            gaps,
        )
        unknown_fields = sorted((blocking | non_blocking) - set(TARGET_GAP_MESSAGES))
        if unknown_fields:
            gaps.append(f"evaluator_policy.{mode_id} contains unknown target fields: {', '.join(unknown_fields)}.")
        overlap = sorted(blocking & non_blocking)
        if overlap:
            gaps.append(f"evaluator_policy.{mode_id} has fields in both blocking and non-blocking lists: {', '.join(overlap)}.")
        expected = MODE_REQUIRED_TARGETS.get(mode_id)
        if expected is not None and blocking != expected:
            gaps.append(
                f"evaluator_policy.{mode_id}.blocking_target_fields does not match work_evaluator.MODE_REQUIRED_TARGETS."
            )
        if mode_id != "quick" and "mode_selection_record_targets" not in blocking:
            gaps.append(f"evaluator_policy.{mode_id} must block on mode_selection_record_targets.")
        if mode_id != "quick" and "omission_check_targets" not in blocking:
            gaps.append(f"evaluator_policy.{mode_id} must block on omission_check_targets.")

    for mode_id in REQUIRED_MODE_IDS - policy_ids:
        warnings.append(f"evaluator_policy for {mode_id} could not be checked because it is missing.")


def _string_set(value: Any, field_name: str, gaps: list[str]) -> set[str]:
    if not isinstance(value, list):
        gaps.append(f"{field_name} must be a list.")
        return set()
    if not all(isinstance(item, str) for item in value):
        gaps.append(f"{field_name} must contain only strings.")
        return set()
    return set(value)


def _mode_records(registry: dict[str, Any]) -> list[dict[str, Any]]:
    modes = registry.get("modes", [])
    if not isinstance(modes, list):
        raise ValueError("modes must be a list.")
    return [mode for mode in modes if isinstance(mode, dict)]

