  const monitorShell = readText("renderer/workspace-monitor/components/MonitorShell.tsx");
  const workspacePersistenceReady = [
    "get_desktop_workspace_state",
    "set_desktop_workspace_path",
    "clone_desktop_workspace",
    "DesktopWorkspaceStateReport",
    "desktop_workspace_state_path"
  ].every((token) => tauriLib.includes(token)) && monitorShell.includes("Workspace Host");

  const groups = [
    group("runtime_data", "Runtime Data Boundary", [
      check("runtime_roots_command", "Runtime root command exposed", tauriLib.includes("list_runtime_data_roots"), "list_runtime_data_roots command exists."),
      check("task_runs_outside_source", "Task-run store outside source", tauriLib.includes("runtime_data_store_base_path") && tauriLib.includes("task_runs_base_path"), "Task-run records are stored under app data runtime roots."),
      check("agent_workspace_plane", "Agent workspace plane declared", serializedRuntimeBoundary.includes("agent_workspace"), "Agent runtime work has a plane separate from reusable definitions.")
    ]),
    group("customer_payload", "Customer Payload", [
      check("customer_snapshot_build", "Customer snapshot build configured", pkg.scripts?.["renderer:build"]?.includes("build:customer"), "Tauri build path uses customer snapshot mode."),
      check("bundle_audit_gate", "Customer bundle audit gate configured", pkg.scripts?.["renderer:build"]?.includes("customer-bundle:audit"), "Customer bundle audit runs after renderer build."),
      check("source_payload_rules", "Source/private payload rules declared", serializedRuntimeBoundary.includes("_private/") && serializedRuntimeBoundary.includes("development repository source tree"), "Private and source-tree payloads are disallowed.")
    ]),
    group("support_diagnostics", "Support Diagnostics", [
      check("support_bundle_command", "Support diagnostic command exposed", tauriLib.includes("create_support_diagnostic_bundle"), "Runtime can create support diagnostic bundles."),
      check("redacted_support_export", "Support export is redacted", tauriLib.includes("redacted") && tauriLib.includes("task-run-summary.redacted.json"), "Support bundle uses redacted bounded summaries."),
      check("support_ui_surface", "Support controls visible in app", monitorShell.includes("Support Diagnostic Bundle"), "Desktop UI exposes support bundle controls.")
    ]),
    group("provider_accounts", "Provider Accounts", [
      check("provider_credentials_redacted", "Provider credential reports are redacted", tauriLib.includes("secret_preview") && tauriLib.includes("credential_secret_preview"), "Credential reports expose only preview/status metadata."),
      check("provider_direct_task_command", "Direct provider task command exposed", tauriLib.includes("run_provider_agent_task") && tauriLib.includes("ProviderAgentTaskReport"), "Connected provider accounts can run model tasks without a shell command."),
      check("local_model_catalog_command", "Local model catalog command exposed", tauriLib.includes("list_provider_models") && tauriLib.includes("ProviderModelCatalogReport") && tauriLib.includes("Ollama / Local"), "The native runtime can list local Ollama models without an API key."),
      check("provider_direct_task_ui", "Direct provider task UI visible", monitorShell.includes("agent-provider-run-controls") && monitorShell.includes("agent-model-picker") && monitorShell.includes("list_provider_models") && monitorShell.includes("run_provider_agent_task"), "Search Agent Work Chat exposes provider account and model controls.")
    ]),
    group("production_agent_blueprints", "Production Agent Blueprints", [
      check("agentcore_blueprint_ui", "AgentCore-style blueprint UI visible", monitorShell.includes("AgentCoreBlueprintPanel") && monitorShell.includes("agentcore-blueprint-panel"), "Agents screen exposes production blueprints derived from public AgentCore references."),
      check("agentcore_blueprint_prefill", "Blueprints fill runnable inputs", monitorShell.includes("applyAgentCoreBlueprint") && monitorShell.includes("setAgentFactoryForm") && monitorShell.includes("setSearchAgentRunForm"), "Blueprint application fills Search Agent Work Chat and Agent Core inputs."),
      check("agentcore_quick_builder_proposal", "Blueprints create proposals directly", monitorShell.includes("AgentCore Quick Builder") && monitorShell.includes("createAgentCoreBlueprintProposal") && monitorShell.includes("create_agent_factory_proposal"), "AgentCore-style blueprint selection can call the native Agent Core proposal writer."),
      check("local_python_execution_boundary", "Agent execution stays local", monitorShell.includes("local_python_agent_runtime") && monitorShell.includes("local_process_execution") && serializedRegistry.includes("local Python execution"), "AgentCore-style proposals declare local Python/process execution as the host boundary."),
      check("agentcore_reference_recorded", "AgentCore reference recorded", serializedRegistry.includes("production_agent_blueprints") && serializedUserFlow.includes("awslabs_agentcore_samples"), "Service and user-flow registries record AgentCore-style production blueprint behavior.")
    ]),
    group("workspace_onboarding", "Workspace Onboarding", [
      check("first_run_docs", "First-run onboarding documented", existsSync(path.join(root, "docs/first-run-onboarding.ko.md")), "First-run onboarding document exists."),
      check("workspace_flow_registry", "Workspace flow registered", serializedUserFlow.includes("workspace") && serializedUserFlow.includes("first-run"), "User flow registry includes workspace and first-run language."),
      check("runtime_workspace_persistence", "Runtime workspace chooser enforced", workspacePersistenceReady, "Workspace host commands persist app-owned import/clone/active workspace state.", "warning")
    ]),
    group("privacy_logging", "Privacy & Logging", [
      check("privacy_controls_declared", "Privacy controls declared", serializedRuntimeBoundary.includes("privacy_controls"), "Runtime boundary registry declares privacy controls."),
      check("support_redaction_policy", "Support redaction policy declared", serializedRuntimeBoundary.includes("support_diagnostic"), "Support diagnostic behavior is part of the runtime boundary."),
      check("raw_private_content_not_exported", "Raw private content excluded", serializedRuntimeBoundary.includes("Store real sensitive local files under _private/sensitive/") || serializedRuntimeBoundary.includes("_private/"), "Private vault content is not part of support/customer payload.")
    ]),
    group("signed_distribution", "Signed Distribution", [
      check("internal_release_preflight", "Internal release preflight passes", releaseInternal.blockers.length === 0, releaseInternal.releaseClaim),
      check("hardened_runtime", "Hardened runtime enabled", tauriConfig.bundle?.macOS?.hardenedRuntime === true, "macOS hardened runtime is enabled."),
      check("public_signing_notarization", "Public signing and notarization configured", releasePublic.blockers.length === 0, releasePublic.blockers.join("; ") || "Public release preflight has no blockers.", mode === "public" ? "blocked" : "warning")
    ]),
    group("update_recovery", "Update & Recovery", [
      check("updater_policy_registry", "Updater is a release gate", serializedRegistry.includes("updater_is_a_release_gate"), "Service readiness registry treats updater as a public release gate."),
      check("tauri_updater_configured", "Signed updater channel configured", updaterConfigured(pkg, tauriConfig), "Tauri updater plugin and endpoint are not configured yet.", mode === "public" ? "blocked" : "warning"),
      check("clean_machine_smoke_recorded", "Clean-machine smoke recorded", false, "Clean-machine install/open/update smoke is still pending.", mode === "public" ? "blocked" : "warning")
    ])
  ];

  const allChecks = groups.flatMap((item) => item.checks);
  const internalBlockers = allChecks.filter((item) => item.status === "blocked" && item.requiredForInternal).map((item) => item.label);
  const publicBlockers = allChecks
    .filter((item) => ["blocked", "warning"].includes(item.status) && item.requiredForPublic)
    .map((item) => item.label);
  const warnings = allChecks.filter((item) => item.status === "warning").map((item) => item.label);
  const score = readinessScore(allChecks);
  const status = internalBlockers.length
    ? "service_internal_blocked"
    : publicBlockers.length
      ? "service_internal_ready_public_blocked"
      : "service_public_release_ready_pending_signoff";

  return {
    status,
    mode,
    reportOnly,
    score,
    generatedAt: new Date().toISOString(),
    groups,
    blockers: mode === "public" ? publicBlockers : internalBlockers,
    publicBlockers,
    warnings,
    nextActions: nextActionsFromChecks(allChecks),
    releaseInternal,
    releasePublic,
    serviceClaim: publicBlockers.length
      ? "Internal service readiness is visible, but public service release remains blocked until signing, notarization, updater, and clean-machine smoke are complete."
      : "Public service readiness checks have no known blockers; still run clean release validation before final release language."
  };
}

function group(id, label, checks) {
  const blocked = checks.some((item) => item.status === "blocked");
  const warning = checks.some((item) => item.status === "warning");
  return {
    id,
    label,
    status: blocked ? "blocked" : warning ? "warning" : "passed",
    passedChecks: checks.filter((item) => item.status === "passed").length,
    totalChecks: checks.length,
    checks
  };
}

function check(id, label, passed, detail, fallbackStatus = "blocked") {
  return {
    id,
    label,
    status: passed ? "passed" : fallbackStatus,
    detail,
    requiredForInternal: fallbackStatus === "blocked" && !["public_signing_notarization", "tauri_updater_configured", "clean_machine_smoke_recorded", "runtime_workspace_persistence"].includes(id),
    requiredForPublic: true
  };
}

function updaterConfigured(pkg, tauriConfig) {
  const hasDependency = Boolean(pkg.dependencies?.["@tauri-apps/plugin-updater"] || pkg.devDependencies?.["@tauri-apps/plugin-updater"]);
  const endpoints = tauriConfig.plugins?.updater?.endpoints || tauriConfig.plugins?.updater?.pubkey || [];
  return hasDependency && (Array.isArray(endpoints) ? endpoints.length > 0 : Boolean(endpoints));
}

function readinessScore(checks) {
  if (!checks.length) {
    return 0;
  }
  const total = checks.reduce((sum, item) => {
    if (item.status === "passed") {
      return sum + 100;
    }
    if (item.status === "warning") {
      return sum + 60;
    }
    return sum;
  }, 0);
  return Math.round(total / checks.length);
}

function nextActionsFromChecks(checks) {
  return checks
    .filter((item) => item.status !== "passed")
    .map((item) => ({
      checkId: item.id,
      label: item.label,
      status: item.status,
      action: item.detail
    }))
    .slice(0, 8);
}

function readJson(relativePath) {
  return JSON.parse(readText(relativePath));
}

function readText(relativePath) {
  return readFileSync(path.join(root, relativePath), "utf8");
}

function parseArgs(argv) {
  const modeIndex = argv.indexOf("--mode");
  const mode = modeIndex >= 0 ? argv[modeIndex + 1] || "internal" : "internal";
  if (!["internal", "public"].includes(mode)) {
    throw new Error(`Unsupported service readiness mode: ${mode}`);
  }
  return {
    mode,
    reportOnly: argv.includes("--report-only")
  };
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const report = checkServiceReadiness(parseArgs(process.argv.slice(2)));
  console.log(JSON.stringify(report, null, 2));
  if (report.mode === "public" && report.publicBlockers.length && !report.reportOnly) {
    process.exitCode = 1;
  }
  if (report.mode === "internal" && report.blockers.length && !report.reportOnly) {
    process.exitCode = 1;
  }
}

import { spawnSync } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";

import { runCustomerBundleAudit } from "./check-customer-bundle.mjs";
import { checkReleaseReadiness } from "./check-release-readiness.mjs";
import { checkServiceReadiness } from "./check-service-readiness.mjs";
import { projectRoot, repoRoot, tauriRoot } from "./desktop-pipeline/paths.mjs";

const requiredFiles = [
  "package.json",
  "src-tauri/tauri.conf.json",
  "renderer/workspace-monitor/package.json",
  "scripts/desktop-pipeline.mjs",
  "scripts/desktop-pipeline/definitions.mjs",
  "scripts/desktop-pipeline/runner.mjs",
  "scripts/tauri-before-build-prepared.mjs"
];

function main(argv = process.argv.slice(2)) {
  const jsonOutput = argv.includes("--json");
  const report = buildDoctorReport();

  if (jsonOutput) {
    console.log(JSON.stringify(report, null, 2));
  } else {
    printHumanReport(report);
  }

  if (report.summary.failures > 0) {
    process.exitCode = 1;
  }
}

export function buildDoctorReport() {
  const checks = [
    checkFile("Root pnpm lockfile", path.join(repoRoot, "pnpm-lock.yaml")),
    ...requiredFiles.map((relativePath) => checkFile(relativePath, path.join(projectRoot, relativePath))),
    checkPackageScripts(),
    commandCheck("Node runtime", "node", ["--version"], repoRoot),
    commandCheck("pnpm via Corepack", "corepack", ["pnpm", "--version"], repoRoot),
    commandCheck("Rust cargo", "cargo", ["--version"], tauriRoot),
    commandCheck("Rust compiler", "rustc", ["--version"], tauriRoot),
    commandCheck("Tauri CLI", "corepack", ["pnpm", "--filter", "platform-desktop-app", "exec", "tauri", "--version"], repoRoot),
    commandCheck("Playwright CLI", "corepack", ["pnpm", "--filter", "workspace-monitor", "exec", "playwright", "--version"], repoRoot),
    checkPlaywrightBrowsers(),
    checkCustomerBundle(),
    checkInternalRelease(),
    checkPublicReleaseGates()
  ];

  const summary = summarize(checks);
  return {
    status: summary.failures > 0 ? "desktop_doctor_failed" : summary.warnings > 0 ? "desktop_doctor_ready_with_warnings" : "desktop_doctor_ready",
    generatedAt: new Date().toISOString(),
    summary,
    checks,
    nextCommands: nextCommands(summary)
  };
}

function checkFile(label, filePath) {
  return {
    id: idFromLabel(label),
    label,
    status: existsSync(filePath) ? "passed" : "failed",
    detail: path.relative(repoRoot, filePath).split(path.sep).join("/")
  };
}

function checkPackageScripts() {
  const rootPkg = readJson(path.join(repoRoot, "package.json"));
  const pkg = readJson(path.join(projectRoot, "package.json"));
  const monitorPkg = readJson(path.join(projectRoot, "renderer/workspace-monitor/package.json"));
  const requiredRootScripts = [
    "desktop:setup",
    "desktop:verify:quick",
    "desktop:verify",
    "desktop:renderer:build",
    "desktop:package:internal",
    "desktop:release:report",
    "desktop:doctor"
  ];
  const requiredProjectScripts = [
    "doctor",
    "setup",
    "verify:quick",
    "verify",
    "renderer:build",
    "package:internal",
    "deploy:public:report",
    "tauri:build:prepared"
  ];
  const missing = [
    ...requiredRootScripts.filter((scriptName) => !rootPkg.scripts?.[scriptName]).map((scriptName) => `root:${scriptName}`),
    ...requiredProjectScripts.filter((scriptName) => !pkg.scripts?.[scriptName]).map((scriptName) => `desktop:${scriptName}`),
    ...["install:browsers", "build:customer"].filter((scriptName) => !monitorPkg.scripts?.[scriptName]).map((scriptName) => `monitor:${scriptName}`)
  ];

  return {
    id: "package_scripts",
    label: "Desktop package scripts",
    status: missing.length ? "failed" : "passed",
    detail: missing.length ? `Missing scripts: ${missing.join(", ")}` : "Required setup, verify, renderer, package, release, browser, and doctor scripts are present."
  };
}

function commandCheck(label, command, args, cwd) {
  const result = spawnSync(command, args, {
    cwd,
    encoding: "utf8",
    shell: false,
    timeout: 20_000
  });
  const output = normalizeOutput(`${result.stdout || ""}\n${result.stderr || ""}`);
  return {
    id: idFromLabel(label),
    label,
    status: result.status === 0 ? "passed" : "failed",
    detail: output || result.error?.message || `${command} ${args.join(" ")} exited with ${String(result.status)}`
  };
}

function checkPlaywrightBrowsers() {
  const result = spawnSync("corepack", ["pnpm", "--filter", "workspace-monitor", "exec", "playwright", "install", "--list"], {
    cwd: repoRoot,
    encoding: "utf8",
    shell: false,
    timeout: 20_000
  });
  const output = normalizeOutput(`${result.stdout || ""}\n${result.stderr || ""}`);
  const hasHeadlessShell = output.includes("chromium_headless_shell");
  return {
    id: "playwright_browsers",
    label: "Playwright browser cache",
    status: result.status === 0 && hasHeadlessShell ? "passed" : "failed",
    detail: hasHeadlessShell ? "Chromium headless shell is installed for the current Playwright cache." : output || "Chromium headless shell was not found."
  };
}

function checkCustomerBundle() {
  const report = runCustomerBundleAudit({ allowMissingDist: true, allowStaleGeneratedSnapshots: true });
  return {
    id: "customer_bundle",
    label: "Customer renderer bundle boundary",
    status: report.failures.length ? "failed" : report.warnings.length ? "warning" : "passed",
    detail: report.failures[0] || report.warnings[0] || `${report.checkedSnapshots.length} snapshots checked; ${report.scannedDistFiles} dist files scanned.`
  };
}

function checkInternalRelease() {
  const report = checkReleaseReadiness({ mode: "internal", reportOnly: true });
  return {
    id: "internal_release_preflight",
    label: "Internal release preflight",
    status: report.blockers.length ? "failed" : report.warnings.length ? "warning" : "passed",
    detail: report.blockers[0] || report.warnings[0] || "Internal release preflight has no blockers."
  };
}

function checkPublicReleaseGates() {
  const release = checkReleaseReadiness({ mode: "public", reportOnly: true });
  const service = checkServiceReadiness({ mode: "public", reportOnly: true });
  const blockers = [...release.blockers, ...service.publicBlockers];
  return {
    id: "public_release_gates",
    label: "Public release gates",
    status: blockers.length ? "warning" : "passed",
    detail: blockers.length ? `Still blocked for public release: ${Array.from(new Set(blockers)).join("; ")}` : "No public release blockers reported."
  };
}

function summarize(checks) {
  return {
    total: checks.length,
    passed: checks.filter((check) => check.status === "passed").length,
    warnings: checks.filter((check) => check.status === "warning").length,
    failures: checks.filter((check) => check.status === "failed").length
  };
}

function nextCommands(summary) {
  if (summary.failures > 0) {
    return [
      "corepack pnpm run desktop:setup",
      "corepack pnpm run desktop:doctor"
    ];
  }
  return [
    "corepack pnpm run desktop:verify:quick",
    "corepack pnpm run desktop:verify",
    "corepack pnpm run desktop:package:internal"
  ];
}

function printHumanReport(report) {
  console.log(`[desktop-doctor] ${report.status}`);
  console.log(`[desktop-doctor] passed=${report.summary.passed} warnings=${report.summary.warnings} failures=${report.summary.failures}`);
  for (const check of report.checks) {
    const marker = check.status === "passed" ? "PASS" : check.status === "warning" ? "WARN" : "FAIL";
    console.log(`\n[${marker}] ${check.label}`);
    console.log(`  ${check.detail}`);
  }
  console.log("\nNext commands:");
  for (const command of report.nextCommands) {
    console.log(`  - ${command}`);
  }
}

function idFromLabel(label) {
  return label.toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_|_$/g, "");
}

function normalizeOutput(output) {
  return output.trim().split("\n").map((line) => line.trim()).filter(Boolean).slice(0, 8).join(" | ");
}

function readJson(filePath) {
  return JSON.parse(readFileSync(filePath, "utf8"));
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

